  if (!BULLET_PROPERTY_BLOCK_ID_RE.test(String(id || ""))) {
    return false;
  }

  const re = new RegExp(
    `(^|[ \\t])\\^${escapeRegExp(id)}(?=$|[ \\t\\r\\n])`,
    "gm",
  );
  return re.test(String(content || ""));
