    const text = value.trim();
    const wiki = text.match(/^\[\[([^\]|#]+)(?:[#|][^\]]*)?\]\]$/);
    const name = (wiki ? wiki[1] : text)
      .trim()
      .split("/")
      .pop()
      .replace(/\.md$/i, "")
      .trim();
