          parentIsTarget,
          insertionAt,
          expectedInsertion,
          activeIsMoved,
          pinnedPreserved: sourceLeaf.pinned === beforePinned,
          sourceShapeValid,
          sourceCollapsed,
          targetSelectedIsMoved: targetSelected === sourceLeaf,
