function getLocalDateStart(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function compareLocalDates(firstDate, secondDate) {
  const firstTime = getLocalDateStart(firstDate).getTime();
  const secondTime = getLocalDateStart(secondDate).getTime();
  if (firstTime === secondTime) {
    return 0;
  }

  return firstTime < secondTime ? -1 : 1;
}

function addLocalDateDays(date, days) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

function getLocalDayOffset(baseDate, targetDate) {
  const baseTime = getLocalDateStart(baseDate).getTime();
  const targetTime = getLocalDateStart(targetDate).getTime();
  return Math.round((targetTime - baseTime) / 86_400_000);
}

function formatRelativeDayOffset(offset) {
  const days = Number(offset);
  if (!Number.isFinite(days)) {
    return "";
  }
  if (days === 0) {
    return "today";
  }
  if (days === 1) {
    return "tomorrow";
  }
  if (days === -1) {
    return "yesterday";
  }
  if (days > 1) {
    return `in ${days} days`;
  }
  return `${Math.abs(days)} days ago`;
}

function formatRelativeDayRange(minOffset, maxOffset) {
  const min = Number(minOffset);
  const max = Number(maxOffset);
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    return "";
  }
  if (min === max) {
    return formatRelativeDayOffset(min);
  }
  if (min >= 1) {
    return `in ${min}–${max} days`;
  }
  return `${formatRelativeDayOffset(min)} to ${formatRelativeDayOffset(max)}`;
}

function rollPriorityScheduledDateWithOffset(
  level,
  baseDate,
  random = Math.random,
) {
  const span = level.maxDays - level.minDays + 1;
  const rolledOffset = Math.floor(random() * span);
  const offset =
    level.minDays + clampNumber(rolledOffset, 0, Math.max(0, span - 1));
  return Object.freeze({
    date: addLocalDateDays(getLocalDateStart(baseDate), offset),
    offset,
  });
}

function rollPriorityScheduledDate(level, baseDate, random = Math.random) {
  return rollPriorityScheduledDateWithOffset(level, baseDate, random).date;
}

// Roll a recommendation date that never lands on the task's current `scheduled`
// date when the window has room. Draws uniformly from the window minus the
// current date's offset, and only when that offset is inside the window and the
// window spans more than one day; otherwise behaves exactly like
// rollPriorityScheduledDateWithOffset. A skipped automatic entry (unchanged
// date) would otherwise silently lose a streak step.
function rollPriorityRecommendationDate(
  level,
  baseDate,
  random = Math.random,
  avoidValue = "",
) {
  const bounds = getPriorityRollBounds(level);
  const start = getLocalDateStart(baseDate);
  if (!bounds) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const span = bounds.maxDays - bounds.minDays + 1;
  if (!(span > 1)) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidText = normalizeBulletPropertyValue(avoidValue);
  const avoidMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(avoidText);
  if (!avoidMatch) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidDate = new Date(
    Number(avoidMatch[1]),
    Number(avoidMatch[2]) - 1,
    Number(avoidMatch[3]),
  );
  if (!Number.isFinite(avoidDate.getTime())) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const avoidOffset = getLocalDayOffset(start, avoidDate);
  if (avoidOffset < bounds.minDays || avoidOffset > bounds.maxDays) {
    return rollPriorityScheduledDateWithOffset(level, baseDate, random);
  }
  const rolled = Math.floor(random() * (span - 1));
  const clamped = clampNumber(rolled, 0, Math.max(0, span - 2));
  let offset = bounds.minDays + clamped;
  if (offset >= avoidOffset) {
    offset += 1;
  }
  return Object.freeze({
    date: addLocalDateDays(start, offset),
    offset,
  });
}

function addLocalDateMonths(date, months) {
  const targetMonthIndex = date.getMonth() + months;
  const targetYear = date.getFullYear() + Math.floor(targetMonthIndex / 12);
  const normalizedMonthIndex = ((targetMonthIndex % 12) + 12) % 12;
  const targetMonth = normalizedMonthIndex + 1;
  const targetDay = Math.min(
    date.getDate(),
    getDaysInMonth(targetYear, targetMonth),
  );

  return new Date(targetYear, normalizedMonthIndex, targetDay);
}

function getDaysUntilWeekday(date, weekday, allowToday) {
  const delta = (weekday - date.getDay() + 7) % 7;
  return delta === 0 && !allowToday ? 7 : delta;
}

function formatBulletPropertyDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getBulletPropertyDateWeekday(date) {
  return BULLET_PROPERTY_WEEKDAY_NAMES[date.getDay()] || "";
}

function createBulletPropertyDateValueItem(
  label,
  date,
  currentValue,
  options = {},
) {
  const value = formatBulletPropertyDate(date);
  const weekday = getBulletPropertyDateWeekday(date);
  return {
    kind: "value",
    value,
    label,
    detail: `${value} · ${weekday}`,
    current: value === currentValue,
    dynamic: !!options.dynamic,
    searchText: `${label} ${value} ${weekday}`,
  };
}

function createBulletPropertyDateItems(baseDate, currentValue, options = {}) {
  const today = getLocalDateStart(baseDate);
  const saturday = addLocalDateDays(
    today,
    getDaysUntilWeekday(today, 6, true),
  );
  const sunday = addLocalDateDays(today, getDaysUntilWeekday(today, 0, true));
  const nextMonday = addLocalDateDays(
    today,
    getDaysUntilWeekday(today, 1, false),
  );

  const presets = [];
  if (options.includeToday !== false) {
    presets.push(["Today", today]);
  }
  presets.push(
    ["Tomorrow", addLocalDateDays(today, 1)],
    ["In 2 days", addLocalDateDays(today, 2)],
    ["In 3 days", addLocalDateDays(today, 3)],
    ["This Saturday", saturday],
    ["This Sunday", sunday],
    ["Next Monday", nextMonday],
    ["In 1 week", addLocalDateDays(today, 7)],
    ["In 2 weeks", addLocalDateDays(today, 14)],
    ["In 1 month", addLocalDateMonths(today, 1)],
  );
  return presets.map(([label, date]) =>
    createBulletPropertyDateValueItem(label, date, currentValue),
  );
}

function createPriorityRollDateItem(
  level,
  baseDate,
  currentValue,
  random = Math.random,
) {
  const roll = rollPriorityScheduledDateWithOffset(level, baseDate, random);
  const date = roll.date;
  const value = formatBulletPropertyDate(date);
  const weekday = getBulletPropertyDateWeekday(date);
  return {
    kind: "value",
    value,
    label: `${level.label} roll`,
    detail: `${value} · ${weekday} · ${formatPriorityRollWindowText(level)}`,
    current: value === currentValue,
    dynamic: false,
    priorityRoll: true,
    level,
    rolledDays: roll.offset,
    searchText: `${level.label} roll ${value} ${weekday} random priority`,
  };
}

function getPriorityLevelIconName(levelIndex) {
  if (levelIndex === 0) {
    return "signal-high";
  }
  if (levelIndex === 1) {
    return "signal-medium";
  }
  if (levelIndex === 2) {
    return "signal-low";
  }
  return "signal-zero";
}

function normalizePriorityLevelIndex(property, level, levelIndex) {
  if (Number.isInteger(levelIndex) && levelIndex >= 0) {
    return levelIndex;
  }
  const levels = property && Array.isArray(property.levels)
    ? property.levels
    : [];
  const directIndex = levels.indexOf(level);
  if (directIndex >= 0) {
    return directIndex;
  }
  const levelLabel = level && normalizeBulletPropertyValue(level.label);
  const levelValue = level && normalizeBulletPropertyValue(level.value);
  const matchingIndex = levels.findIndex(
    (candidate) =>
      normalizeBulletPropertyValue(candidate && candidate.label) === levelLabel &&
      normalizeBulletPropertyValue(candidate && candidate.value) === levelValue,
  );
  return matchingIndex >= 0 ? matchingIndex : 0;
}

function parsePriorityNoticeScheduledValue(value) {
  const text = normalizeBulletPropertyValue(value);
  const validation = validateProjectScheduledDate(text);
  if (!validation.valid) {
    return Object.freeze({
      text: text || validation.value,
      valid: false,
      date: null,
      time: null,
      weekday: "",
    });
  }
  const date = projectScheduleLocalDate(validation);
  return Object.freeze({
    text: validation.value,
    valid: true,
    date,
    time: getLocalDateStart(date).getTime(),
    weekday: getBulletPropertyDateWeekday(date),
  });
}

function getPriorityNoticeScheduleSummary(values, baseDate) {
  const entries = (Array.isArray(values) ? values : [values])
    .map(parsePriorityNoticeScheduledValue)
    .filter((entry) => entry.text);
  if (entries.length === 0) {
    return Object.freeze({
      exactDateText: "",
      dateStartText: "",
      dateEndText: "",
      weekdayText: "",
      relativeText: "",
      textDateText: "",
      dateText: "",
    });
  }
  const validEntries = entries.filter((entry) => entry.valid);
  if (validEntries.length !== entries.length) {
    if (entries.length === 1) {
      return Object.freeze({
        exactDateText: entries[0].text,
        dateStartText: entries[0].text,
        dateEndText: "",
        weekdayText: "",
        relativeText: "",
        textDateText: entries[0].text,
        dateText: entries[0].text,
      });
    }
    const firstText = entries[0].text;
    const lastText = entries[entries.length - 1].text;
    const textDateText = `${firstText} to ${lastText}`;
    return Object.freeze({
      exactDateText: `${firstText} → ${lastText}`,
      dateStartText: firstText,
      dateEndText: lastText,
      weekdayText: "",
      relativeText: "",
      textDateText,
      dateText: textDateText,
    });
  }

  const sortedEntries = validEntries
    .slice()
    .sort((first, second) => first.time - second.time);
  const first = sortedEntries[0];
  const last = sortedEntries[sortedEntries.length - 1];
  if (first.time === last.time) {
    const textDateText = `${first.text} · ${first.weekday}`;
    return Object.freeze({
      exactDateText: first.text,
      dateStartText: first.text,
      dateEndText: "",
      weekdayText: first.weekday,
      relativeText: formatRelativeDayOffset(
        getLocalDayOffset(baseDate, first.date),
      ),
      textDateText,
      dateText: textDateText,
    });
  }

  const minOffset = getLocalDayOffset(baseDate, first.date);
  const maxOffset = getLocalDayOffset(baseDate, last.date);
  const textDateText = `${first.text} to ${last.text}`;
  return Object.freeze({
    exactDateText: `${first.text} → ${last.text}`,
    dateStartText: first.text,
    dateEndText: last.text,
    weekdayText: "",
    relativeText: formatRelativeDayRange(minOffset, maxOffset),
    textDateText,
    dateText: textDateText,
  });
}

function normalizePriorityNoticeCount(value) {
  return Math.max(0, Math.floor(numericOrDefault(value, 0)));
}

function getPriorityNoticeRecoveryCounts(outcome = {}) {
  const recoveryCounts = outcome.recoveryCounts || {};
  return Object.freeze({
    ready: normalizePriorityNoticeCount(
      recoveryCounts.ready ?? outcome.recoveredReadyTaskCount,
    ),
    next: normalizePriorityNoticeCount(
      recoveryCounts.next ?? outcome.recoveredNextTaskCount,
    ),
    inProgress: normalizePriorityNoticeCount(
      recoveryCounts.inProgress ?? outcome.recoveredInProgressTaskCount,
    ),
    stillBlocked: normalizePriorityNoticeCount(
      recoveryCounts.stillBlocked ?? outcome.stillBlockedTaskCount,
    ),
    deferred: normalizePriorityNoticeCount(
      recoveryCounts.deferred ?? outcome.deferredRecoveryTaskCount,
    ),
  });
}

function getPriorityNoticeBlockedText(count, scope) {
  if (count <= 0) {
    return "";
  }
  if (scope === "task") {
    return "marked task Blocked";
  }
  return `marked ${formatCountLabel(count, "task")} Blocked`;
}

function getPriorityNoticeOutcomeParts(outcome = {}, scope = "task") {
  const parts = [];
  if (scope === "counted") {
    parts.push(
      ...getCountedTaskNoticeParts(
        outcome.session,
        normalizePriorityNoticeCount(outcome.unchangedTaskCount),
      ),
    );
  }
  const propagatedScheduleTaskCount = normalizePriorityNoticeCount(
    outcome.propagatedScheduleTaskCount ?? outcome.scheduledTaskCount,
  );
  if (propagatedScheduleTaskCount > 0) {
    parts.push(
      `scheduled ${formatCountLabel(propagatedScheduleTaskCount, "task")}`,
    );
  }
  const removedHideTaskCount = normalizePriorityNoticeCount(
    outcome.removedHideTaskCount,
  );
  if (removedHideTaskCount > 0) {
    parts.push(
      `removed #hide from ${formatCountLabel(removedHideTaskCount, "task")}`,
    );
  }
  const scheduleLoggedTaskCount = normalizePriorityNoticeCount(outcome.scheduleLoggedTaskCount);
  if (scheduleLoggedTaskCount > 0) {
    parts.push(
      scope === "counted" ? `logged reason on ${formatCountLabel(scheduleLoggedTaskCount, "task")}` : "logged reason",
    );
  }
  const schedulingWorkLogWrittenCount = normalizePriorityNoticeCount(
    outcome.schedulingWorkLogWrittenCount,
  );
  if (schedulingWorkLogWrittenCount > 0) {
    parts.push(
      scope === "counted"
        ? `${formatCountLabel(schedulingWorkLogWrittenCount, "Work Log")}`
        : "1 Work Log",
    );
  }
  const blockedText = getPriorityNoticeBlockedText(
    normalizePriorityNoticeCount(outcome.blockedTaskCount),
    scope,
  );
  if (blockedText) {
    parts.push(blockedText);
  }
  const ambiguousTaskCount = normalizePriorityNoticeCount(
    outcome.ambiguousTaskCount ?? outcome.ambiguousProjectTaskCount,
  );
  if (ambiguousTaskCount > 0) {
    parts.push(
      `${formatCountLabel(ambiguousTaskCount, "task")} with multiple scheduled fields unchanged`,
    );
  }
  parts.push(...scheduledRecoveryNoticeParts(getPriorityNoticeRecoveryCounts(outcome)));
  const removedPomodoroLinkCount = normalizePriorityNoticeCount(
    outcome.removedPomodoroLinkCount,
  );
  if (removedPomodoroLinkCount > 0) {
    parts.push(
      `removed ${formatCountLabel(removedPomodoroLinkCount, "Pomodoro link")}`,
    );
  } else if (outcome.pomodoroPruneFailed) {
    parts.push("Pomodoro links not removed");
  }
  return Object.freeze(parts);
}

function getPriorityNoticeChipTone(text) {
  if (/^recovered /.test(text)) {
    return "ok";
  }
  if (/Blocked$/.test(text)) {
    return "warn";
  }
  if (text === "Pomodoro links not removed") {
    return "warn";
  }
  if (/^(scheduled|removed #hide|removed \d+ Pomodoro links?)/.test(text)) {
    return "info";
  }
  if (/^logged reason/.test(text)) {
    return "info";
  }
  if (/Work Log$/.test(text)) {
    return "info";
  }
  return "muted";
}

function getPriorityNoticeChipText(text) {
  const markedMatch = /^marked (?:(\d+) tasks?|task) Blocked$/.exec(text);
  if (markedMatch) {
    return markedMatch[1] ? `${markedMatch[1]} Blocked` : "Blocked";
  }
  const loggedMatch = /^logged reason(?: on (\d+) tasks?)?$/.exec(text);
  if (loggedMatch) {
    return loggedMatch[1] ? `${loggedMatch[1]} logged` : "logged";
  }
  const workLogMatch = /^(\d+) Work Logs?$/.exec(text);
  if (workLogMatch) {
    return workLogMatch[1] === "1" ? "1 Work Log" : `${workLogMatch[1]} Work Log`;
  }
  if (text === "1 Work Log") {
    return "1 Work Log";
  }
  const pomodoroRemovedMatch = /^removed (\d+) Pomodoro links?$/.exec(text);
  if (pomodoroRemovedMatch) {
    return `${pomodoroRemovedMatch[1]} removed`;
  }
  if (text === "Pomodoro links not removed") {
    return "not removed";
  }
  return text;
}

function formatPriorityNoticeText(model) {
  const parts = [];
  if (model.textHeader) {
    parts.push(model.textHeader);
  }
  if (Array.isArray(model.leadingTextParts)) {
    parts.push(...model.leadingTextParts);
  }
  const dateText = model.textDateText || model.dateText || model.exactDateText;
  if (dateText) {
    const dateLabel = model.textDateLabel || model.dateLabel || "scheduled";
    const relativeText = model.relativeText ? ` · ${model.relativeText}` : "";
    parts.push(`${dateLabel} → ${dateText}${relativeText}`);
  }
  if (Array.isArray(model.outcomeTextParts)) {
    parts.push(...model.outcomeTextParts);
  }
  return parts.join("; ");
}

// ---- src/280-notices-and-dates.js ----
function buildPriorityNoticeModel(options = {}) {
  const property = options.property || {};
  const level = options.level || {};
  const scope = ["task", "counted", "project"].includes(options.scope)
    ? options.scope
    : "task";
  const propertyName = normalizeBulletPropertyName(property.name) || "priority";
  const scheduledName =
    normalizeBulletPropertyName(property.schedules) || "scheduled";
  const levelIndex = normalizePriorityLevelIndex(
    property,
    level,
    options.levelIndex,
  );
  const roll =
    options.roll && typeof options.roll === "object" ? options.roll : null;
  const rollKind =
    roll && typeof roll.kind === "string" ? roll.kind : "";
  const rollFromLevel = normalizeBulletPropertyValue(roll && roll.fromLevel);
  const pill =
    rollKind === "roll" && normalizeBulletPropertyValue(level.label)
      ? `${normalizeBulletPropertyValue(level.label)} roll`
      : rollKind === "decay" && rollFromLevel && normalizeBulletPropertyValue(level.label)
        ? `${rollFromLevel} → ${normalizeBulletPropertyValue(level.label)}`
        : normalizeBulletPropertyValue(level.label);
  const levelValue = normalizeBulletPropertyValue(level.value);
  const taskCount = Math.max(
    1,
    normalizePriorityNoticeCount(options.taskCount || 1),
  );
  const scheduleSummary = getPriorityNoticeScheduleSummary(
    options.scheduledValues || [],
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date()),
  );
  const outcomeTextParts = getPriorityNoticeOutcomeParts(
    options.outcome || {},
    scope,
  );
  const textHeader =
    rollKind === "roll"
      ? `${scheduledName} → ${pill}`
      : rollKind === "decay"
        ? `${propertyName} → ${normalizeBulletPropertyValue(level.label)} (${levelValue}) · decayed from ${rollFromLevel}`
        : scope === "counted"
          ? `${propertyName} → ${pill} (${levelValue}) on ${formatCountLabel(
              taskCount,
              "task",
            )}`
          : `${propertyName} → ${pill} (${levelValue})`;
  // Leading roll chips, before the existing outcome chips. With decay
  // disabled (no step/limit) there are no roll or next chips.
  const leadingChips = [];
  if (rollKind === "roll" && Number.isFinite(Number(roll.step)) && roll.limit !== null && roll.limit !== undefined) {
    leadingChips.push(
      Object.freeze({ text: `roll ${roll.step}/${roll.limit}`, tone: "info" }),
    );
  } else if (rollKind === "decay" && rollFromLevel) {
    leadingChips.push(
      Object.freeze({ text: `decayed from ${rollFromLevel}`, tone: "warn" }),
    );
  }
  if (
    (rollKind === "roll" || rollKind === "decay") &&
    roll &&
    typeof roll.next === "string"
  ) {
    if (roll.next === "decay" && normalizeBulletPropertyValue(roll.nextLabel)) {
      leadingChips.push(
        Object.freeze({
          text: `next ^↵ → ${normalizeBulletPropertyValue(roll.nextLabel)}`,
          tone: "warn",
        }),
      );
    } else if (roll.next === "cancel") {
      leadingChips.push(
        Object.freeze({ text: "next ^↵ cancels", tone: "warn" }),
      );
    }
  }
  const leadingTextParts = leadingChips.map((chip) => chip.text);
  const model = {
    iconName: getPriorityLevelIconName(levelIndex),
    levelIndex,
    levelValue,
    pill,
    countPill: scope === "counted" ? formatCountLabel(taskCount, "task") : "",
    receipt: `[${propertyName}:: ${levelValue}]`,
    dateLabel: scope === "project" ? `${scheduledName} (project)` : scheduledName,
    textDateLabel: scheduledName,
    exactDateText: scheduleSummary.exactDateText,
    dateStartText: scheduleSummary.dateStartText,
    dateEndText: scheduleSummary.dateEndText,
    weekdayText: scheduleSummary.weekdayText,
    textDateText: scheduleSummary.textDateText,
    dateText: scheduleSummary.dateText,
    relativeText: scheduleSummary.relativeText,
    chips: Object.freeze([
      ...leadingChips,
      ...outcomeTextParts.map((part) =>
        Object.freeze({
          text: getPriorityNoticeChipText(part),
          tone: getPriorityNoticeChipTone(part),
        }),
      ),
    ]),
    outcomeTextParts,
    leadingTextParts: Object.freeze(leadingTextParts),
    textHeader,
  };
  model.text = formatPriorityNoticeText(model);
  return Object.freeze(model);
}

// One priority-style card for a counted recommended-roll batch: header icon
// `dices`, pill `Rolled N tasks`, leading `N rolled` / `N decayed` /
// `N cancelled` chips, the rolled date span, then the existing outcome chips
// (Blocked, removed Pomodoro links, skipped, prune-failed). Pure.
function buildBatchPriorityRollNoticeModel(batch, options = {}) {
  const counts = (batch && batch.counts) || {};
  const rolled = Math.max(0, Math.floor(numericOrDefault(counts.roll, 0)));
  const assigned = Math.max(0, Math.floor(numericOrDefault(counts.assign, 0)));
  const assignLabel = normalizeBulletPropertyValue(
    batch && batch.property
      ? getPriorityAssignLevelLabel(batch.property)
      : "",
  );
  const decayed = Math.max(0, Math.floor(numericOrDefault(counts.decay, 0)));
  const cancelled = Math.max(0, Math.floor(numericOrDefault(counts.cancel, 0)));
  const actionable = Math.max(
    0,
    Math.floor(
      numericOrDefault(
        batch && batch.actionableCount,
        rolled + assigned + decayed + cancelled,
      ),
    ),
  );
  const baseDate =
    options.baseDate instanceof Date
      ? getLocalDateStart(options.baseDate)
      : getLocalDateStart(new Date());
  const scheduledValues = Array.isArray(options.scheduledValues)
    ? options.scheduledValues
    : [];
  const scheduleSummary = getPriorityNoticeScheduleSummary(
    scheduledValues,
    baseDate,
  );
  const outcome = options.outcome || {};
  const outcomeTextParts = getPriorityNoticeOutcomeParts(outcome, "counted");
  const leadingChips = [];
  if (rolled > 0) {
    leadingChips.push(
      Object.freeze({
        text: `${rolled} rolled`,
        tone: "info",
      }),
    );
  }
  if (assigned > 0) {
    leadingChips.push(
      Object.freeze({
        text: assignLabel
          ? `${assigned} set ${assignLabel}`
          : `${assigned} set`,
        tone: "info",
      }),
    );
  }
  if (decayed > 0) {
    leadingChips.push(
      Object.freeze({ text: `${decayed} decayed`, tone: "warn" }),
    );
  }
  if (cancelled > 0) {
    leadingChips.push(
      Object.freeze({ text: `${cancelled} cancelled`, tone: "warn" }),
    );
  }
  const leadingTextParts = leadingChips.map((chip) => chip.text);
  const skipped = Math.max(
    0,
    Math.floor(
      numericOrDefault(
        outcome.skippedCount ?? (batch && batch.skippedCount),
        0,
      ),
    ),
  );
  const fullOutcomeParts = skipped > 0
    ? Object.freeze([
        ...outcomeTextParts,
        `${formatCountLabel(skipped, "task")} skipped`,
      ])
    : outcomeTextParts;
  const pill = `Rolled ${formatCountLabel(actionable, "task")}`;
  const model = {
    iconName: "dices",
    levelIndex: null,
    levelValue: "",
    pill,
    countPill: "",
    receipt: "[priority]",
    dateLabel: "scheduled",
    textDateLabel: "scheduled",
    exactDateText: scheduleSummary.exactDateText,
    dateStartText: scheduleSummary.dateStartText,
    dateEndText: scheduleSummary.dateEndText,
    weekdayText: scheduleSummary.weekdayText,
    textDateText: scheduleSummary.textDateText,
    dateText: scheduleSummary.dateText,
    relativeText: scheduleSummary.relativeText,
    chips: Object.freeze([
      ...leadingChips,
      ...fullOutcomeParts.map((part) =>
        Object.freeze({
          text: getPriorityNoticeChipText(part),
          tone: getPriorityNoticeChipTone(part),
        }),
      ),
    ]),
    outcomeTextParts: fullOutcomeParts,
    leadingTextParts: Object.freeze(leadingTextParts),
    textHeader: pill,
  };
  model.text = formatPriorityNoticeText(model);
  return Object.freeze(model);
}

// Guarded lookup of the shared ledger-tools priority-mark renderer,
// mirroring getCancelPlanBudgetChip. Returns api.priorityMarks only when
// it is version 1 or newer with a render function, else null.
function getLedgerPriorityMarksApi(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const api =
      plugins &&
      plugins["bob-ledger-tools"] &&
      plugins["bob-ledger-tools"].api;
    const marks = api && api.priorityMarks;
    if (!marks || typeof marks !== "object") {
      return null;
    }
    if (typeof marks.version !== "number" || marks.version < 1) {
      return null;
    }
    if (typeof marks.render !== "function") {
      return null;
    }
    return marks;
  } catch (error) {
    return null;
  }
}

// Render the shared signal-bar mark into iconEl for a priority notice
// header. The mark is decorative with an inherited color so the existing
// --bob-nh-level-color icon color still applies. Returns true when the
// mark rendered, false when the caller should keep the Lucide icon.
function renderPriorityNoticeMarkIcon(iconEl, model, noticeOptions) {
  try {
    const settings =
      noticeOptions && typeof noticeOptions === "object" ? noticeOptions : {};
    const api = settings.priorityMarks || getLedgerPriorityMarksApi(settings.app);
    if (!api || typeof api.render !== "function") {
      return false;
    }
    const value = model && model.levelValue;
    if (typeof value !== "string" || value === "") {
      return false;
    }
    if (!iconEl || typeof iconEl.createSpan !== "function") {
      return false;
    }
    const host = iconEl.createSpan({ cls: "bob-nh-notice-glyph" });
    let rendered = null;
    try {
      rendered = api.render(host, value, {
        decorative: true,
        inheritColor: true,
      });
    } catch (error) {
      rendered = null;
    }
    if (!rendered) {
      detachNoticeGlyphHost(iconEl, host);
      return false;
    }
    return true;
  } catch (error) {
    return false;
  }
}

function detachNoticeGlyphHost(iconEl, host) {
  try {
    if (host && typeof host.remove === "function") {
      host.remove();
      return;
    }
    if (iconEl && Array.isArray(iconEl.children) && host) {
      const index = iconEl.children.indexOf(host);
      if (index >= 0) {
        iconEl.children.splice(index, 1);
      }
    }
  } catch (error) {
    // Glyph cleanup never throws.
  }
}

function renderPriorityNoticeFragment(model, root, noticeOptions = {}) {
  const levelClass =
    Number.isInteger(model.levelIndex) &&
    model.levelIndex >= 0 &&
    model.levelIndex <= 3
      ? ` is-level-${model.levelIndex}`
      : "";
  const card = root.createDiv({
    cls: `bob-nh-notice${levelClass}`,
    attr: { "aria-label": model.text },
  });
  const headerEl = card.createDiv({ cls: "bob-nh-notice-header" });
  const iconEl = headerEl.createSpan({ cls: "bob-nh-notice-icon" });
  if (!renderPriorityNoticeMarkIcon(iconEl, model, noticeOptions)) {
    applyIcon(iconEl, model.iconName);
  }
  headerEl.createSpan({ cls: "bob-nh-notice-level", text: model.pill });
  if (model.countPill) {
    headerEl.createSpan({ cls: "bob-nh-notice-count", text: model.countPill });
  }
  headerEl.createSpan({ cls: "bob-nh-notice-receipt", text: model.receipt });

  const dateEl = card.createDiv({ cls: "bob-nh-notice-date" });
  const dateHeadingEl = dateEl.createDiv({
    cls: "bob-nh-notice-date-heading",
  });
  const dateIconEl = dateHeadingEl.createSpan({ cls: "bob-nh-notice-date-icon" });
  applyIcon(dateIconEl, "dices");
  dateHeadingEl.createSpan({
    cls: "bob-nh-notice-date-label",
    text: model.dateLabel,
  });
  if (model.relativeText) {
    dateHeadingEl.createSpan({
      cls: "bob-nh-notice-relative",
      text: model.relativeText,
    });
  }
  const receiptEl = dateEl.createDiv({
    cls: "bob-nh-notice-date-receipt",
  });
  receiptEl.createSpan({
    cls: "bob-nh-notice-date-iso",
    text: model.dateStartText || model.exactDateText || "",
  });
  if (model.dateEndText) {
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-arrow",
      text: "→",
      attr: { "aria-hidden": "true" },
    });
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-iso",
      text: model.dateEndText,
    });
  } else if (model.weekdayText) {
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-separator",
      text: "·",
      attr: { "aria-hidden": "true" },
    });
    receiptEl.createSpan({
      cls: "bob-nh-notice-date-weekday",
      text: model.weekdayText,
    });
  }

  if (model.chips.length > 0) {
    const chipsEl = card.createDiv({ cls: "bob-nh-notice-chips" });
    model.chips.forEach((chip) => {
      chipsEl.createSpan({
        cls: `bob-nh-notice-chip is-${chip.tone}`,
        text: chip.text,
      });
    });
  }

  return card;
}

function showPriorityNotice(model, options = {}) {
  const fallbackText =
    model && typeof model.text === "string" ? model.text : String(model || "");
  try {
    if (typeof document === "undefined") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    const fragment = document.createDocumentFragment();
    if (!fragment || typeof fragment.createDiv !== "function") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    renderPriorityNoticeFragment(model, fragment, options);
    showBulletPropertyNotice(fragment, options);
  } catch (error) {
    showBulletPropertyNotice(fallbackText, options);
  }
}

// Read the ledger-tools plan budget for a cancel notice chip, or "" when the
// API is missing or unusable. `dailyContent` is the post-prune daily note
// text, the same input block-id-prompt's unlink notices use.
function getCancelPlanBudgetChip(app, dailyContent) {
  if (typeof dailyContent !== "string") {
    return "";
  }
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const api =
      plugins &&
      plugins["bob-ledger-tools"] &&
      plugins["bob-ledger-tools"].api;
    if (!api || typeof api.planBudget !== "function") {
      return "";
    }
    const budget = api.planBudget({ content: dailyContent });
    if (
      !budget ||
      typeof budget !== "object" ||
      typeof budget.then === "function"
    ) {
      return "";
    }
    const links = budget.links;
    if (
      !links ||
      !Number.isInteger(links.count) ||
      !Number.isInteger(links.cap)
    ) {
      return "";
    }
    const over = links.over === true;
    return `plan ${links.count}/${links.cap}${over ? " 🔴" : ""}`;
  } catch (error) {
    return "";
  }
}

// Pure model for the Cancelled notice card: header (ban icon, `Cancelled`
// level pill, count pill, `[cancelled:: date]` receipt), an italic
// `❌ <reason>` quote (or the muted no-reason/fallback text), and one chip
// per side effect. `model.text` is the aria-label and plain-text fallback.
function buildCancelNoticeModel(options = {}) {
  const count = Math.max(
    1,
    Math.floor(numericOrDefault(options.count, 1)),
  );
  const viaLinks = Boolean(options.viaLinks);
  const dateText = normalizeBulletPropertyValue(options.date);
  const reason = String(options.reason || "");
  const fallbackUsed = Boolean(options.fallbackUsed);
  const scopeText =
    viaLinks && count === 1
      ? "task via Task Link"
      : viaLinks
        ? `${formatCountLabel(count, "task")} via Task Links`
        : count === 1
          ? "task"
          : formatCountLabel(count, "task");
  const countPill =
    viaLinks && count === 1
      ? "via Task Link"
      : !viaLinks && count === 1
        ? ""
        : viaLinks
          ? `${formatCountLabel(count, "task")} via Task Links`
          : formatCountLabel(count, "task");
  const chips = [];
  const removedPomodoroLinkCount = Math.max(
    0,
    Math.floor(numericOrDefault(options.removedPomodoroLinkCount, 0)),
  );
  if (removedPomodoroLinkCount > 0) {
    chips.push(
      Object.freeze({
        text: `removed ${formatCountLabel(removedPomodoroLinkCount, "Pomodoro link")}`,
        tone: "info",
      }),
    );
  }
  const reopened = Math.max(
    0,
    Math.floor(numericOrDefault(options.reopenedDependents, 0)),
  );
  if (options.recoveryRan === true && reopened > 0) {
    chips.push(
      Object.freeze({
        text: `unblocked ${formatCountLabel(reopened, "dependent")}`,
        tone: "ok",
      }),
    );
  }
  const planChip = String(options.planChip || "");
  if (planChip) {
    chips.push(Object.freeze({ text: planChip, tone: "info" }));
  }
  const skippedClosedCount = Math.max(
    0,
    Math.floor(numericOrDefault(options.skippedClosedCount, 0)),
  );
  if (skippedClosedCount > 0) {
    chips.push(
      Object.freeze({
        text: `skipped ${formatCountLabel(skippedClosedCount, "closed")}`,
        tone: "muted",
      }),
    );
  }
  if (options.pomodoroPruneFailed === true) {
    chips.push(
      Object.freeze({ text: "Pomodoro links not removed", tone: "warn" }),
    );
  }
  const parts = [`Cancelled ${scopeText}`];
  if (reason) {
    parts.push(`\u201c${reason}\u201d`);
  } else if (fallbackUsed) {
    parts.push(`\u201c${SCHEDULE_LOG_SKIPPED_REASON_TEXT} · logged\u201d`);
  }
  for (const chip of chips) {
    parts.push(chip.text);
  }
  const reasonBody = reason
    ? `${CANCEL_LOG_EMOJI} ${reason}`
    : fallbackUsed
      ? `${SCHEDULE_LOG_SKIPPED_REASON_TEXT} · logged`
      : "No reason recorded";
  return Object.freeze({
    iconName: "ban",
    level: "Cancelled",
    countPill,
    receipt: `[cancelled:: ${dateText}]`,
    reasonBody,
    reasonMuted: !reason,
    chips: Object.freeze(chips),
    text: parts.join(" · "),
  });
}

function renderCancelNoticeFragment(model, root) {
  const card = root.createDiv({
    cls: "bob-nh-notice is-cancel",
    attr: { "aria-label": model.text },
  });
  const headerEl = card.createDiv({ cls: "bob-nh-notice-header" });
  const iconEl = headerEl.createSpan({ cls: "bob-nh-notice-icon" });
  applyIcon(iconEl, model.iconName || "ban");
  headerEl.createSpan({ cls: "bob-nh-notice-level", text: model.level });
  if (model.countPill) {
    headerEl.createSpan({ cls: "bob-nh-notice-count", text: model.countPill });
  }
  headerEl.createSpan({ cls: "bob-nh-notice-receipt", text: model.receipt });

  const reasonEl = card.createDiv({
    cls: `bob-nh-notice-reason${model.reasonMuted ? " is-muted" : ""}`,
  });
  reasonEl.createSpan({ cls: "bob-nh-notice-reason-text", text: model.reasonBody });

  if (model.chips.length > 0) {
    const chipsEl = card.createDiv({ cls: "bob-nh-notice-chips" });
    model.chips.forEach((chip) => {
      chipsEl.createSpan({
        cls: `bob-nh-notice-chip is-${chip.tone}`,
        text: chip.text,
      });
    });
  }

  return card;
}

function showCancelNotice(model, options = {}) {
  const fallbackText =
    model && typeof model.text === "string" ? model.text : String(model || "");
  try {
    if (typeof document === "undefined") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    const fragment = document.createDocumentFragment();
    if (!fragment || typeof fragment.createDiv !== "function") {
      showBulletPropertyNotice(fallbackText, options);
      return;
    }
    renderCancelNoticeFragment(model, fragment);
    showBulletPropertyNotice(fragment, options);
  } catch (error) {
    showBulletPropertyNotice(fallbackText, options);
  }
}

function parseBulletPropertyTypedDate(query, baseDate) {
  const text = String(query || "").trim();
  if (!text) {
    return null;
  }

  const ymdMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (
    ymdMatch &&
    isValidDateParts(ymdMatch[1], ymdMatch[2], ymdMatch[3])
  ) {
    return new Date(
      parseIntegerText(ymdMatch[1]),
      parseIntegerText(ymdMatch[2]) - 1,
      parseIntegerText(ymdMatch[3]),
    );
  }

  const monthDayMatch = text.match(/^(\d{1,2})[/-](\d{1,2})$/);
  if (monthDayMatch) {
    const monthText = monthDayMatch[1];
    const dayText = monthDayMatch[2];
    let year = baseDate.getFullYear();
    if (!isValidDateParts(String(year), monthText, dayText)) {
      return null;
    }

    let date = new Date(
      year,
      parseIntegerText(monthText) - 1,
      parseIntegerText(dayText),
    );
    if (compareLocalDates(date, baseDate) <= 0) {
      year += 1;
      if (!isValidDateParts(String(year), monthText, dayText)) {
        return null;
      }
      date = new Date(
        year,
        parseIntegerText(monthText) - 1,
        parseIntegerText(dayText),
      );
    }
    return date;
  }

  const offsetMatch = text.match(/^\+(\d+)([dwm])$/i);
  if (offsetMatch) {
    const count = parseIntegerText(offsetMatch[1]);
    const unit = offsetMatch[2].toLowerCase();
    if (!Number.isInteger(count) || count < 0) {
      return null;
    }

    if (unit === "d") {
      return addLocalDateDays(baseDate, count);
    }
    if (unit === "w") {
      return addLocalDateDays(baseDate, count * 7);
    }
    return addLocalDateMonths(baseDate, count);
  }

  return null;
}

function createBulletPropertyTypedDateItem(query, baseDate, currentValue) {
  const date = parseBulletPropertyTypedDate(query, baseDate);
  if (!date) {
    return null;
  }

  const value = formatBulletPropertyDate(date);
  return createBulletPropertyDateValueItem(`Use ${value}`, date, currentValue, {
    dynamic: true,
  });
}

const TYPED_SCHEDULE_ERROR_INVALID = "invalid date";
const TYPED_SCHEDULE_ERROR_NEGATIVE = "negative offset";
const TYPED_SCHEDULE_ERROR_OVERFLOW = "overflow offset";
const TYPED_SCHEDULE_ERROR_AMBIGUOUS = "ambiguous input";
const TYPED_SCHEDULE_MAX_COUNT_DIGITS = 5;
const TYPED_SCHEDULE_WEEKDAY_INDEX = Object.freeze({
  sun: 0,
  sunday: 0,
  mon: 1,
  monday: 1,
  tue: 2,
  tuesday: 2,
  wed: 3,
  wednesday: 3,
  thu: 4,
  thursday: 4,
  fri: 5,
  friday: 5,
  sat: 6,
  saturday: 6,
});

function freezeTypedScheduleResult(date, reason, valid, error) {
  return Object.freeze({
    date: valid && date instanceof Date ? getLocalDateStart(date) : null,
    reason: String(reason || ""),
    valid: valid === true,
    error: valid ? null : error || null,
  });
}

function parseTypedScheduleCount(text) {
  const digits = String(text || "");
  if (!/^\d+$/.test(digits)) {
    return { error: TYPED_SCHEDULE_ERROR_INVALID };
  }
  if (digits.length > TYPED_SCHEDULE_MAX_COUNT_DIGITS) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  const count = Number.parseInt(digits, 10);
  if (!Number.isInteger(count) || count < 0) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  return { count };
}

function typedScheduleDateOrError(date) {
  if (!(date instanceof Date) || !Number.isFinite(date.getTime())) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  const year = date.getFullYear();
  if (year < 1 || year > 9999) {
    return { error: TYPED_SCHEDULE_ERROR_OVERFLOW };
  }
  return { date: getLocalDateStart(date) };
}

function parseTypedScheduleMonthDay(monthText, dayText, baseDate) {
  let year = baseDate.getFullYear();
  if (!isValidDateParts(String(year), monthText, dayText)) {
    return { error: TYPED_SCHEDULE_ERROR_INVALID };
  }
  let date = new Date(
    year,
    parseIntegerText(monthText) - 1,
    parseIntegerText(dayText),
  );
  if (compareLocalDates(date, baseDate) <= 0) {
    year += 1;
    if (!isValidDateParts(String(year), monthText, dayText)) {
      return { error: TYPED_SCHEDULE_ERROR_INVALID };
    }
    date = new Date(
      year,
      parseIntegerText(monthText) - 1,
      parseIntegerText(dayText),
    );
  }
  return typedScheduleDateOrError(date);
}

function applyTypedScheduleUnit(baseDate, count, unit) {
  if (unit === "d") {
    return typedScheduleDateOrError(addLocalDateDays(baseDate, count));
  }
  if (unit === "w") {
    return typedScheduleDateOrError(addLocalDateDays(baseDate, count * 7));
  }
  return typedScheduleDateOrError(addLocalDateMonths(baseDate, count));
}

function matchTypedSchedulePrefix(text) {
  const patterns = [
    { kind: "iso", re: /^(\d{4})-(\d{2})-(\d{2})/ },
    { kind: "month-day", re: /^(\d{1,2})[/-](\d{1,2})/ },
    { kind: "unit", re: /^([+-]?)(\d+)([dwm])/i },
    { kind: "days", re: /^([+-]?)(\d+)/ },
    {
      kind: "weekday",
      re: /^(sunday|monday|tuesday|wednesday|thursday|friday|saturday|sun|mon|tue|wed|thu|fri|sat)/i,
    },
  ];
  for (const pattern of patterns) {
    const match = pattern.re.exec(text);
    if (!match) {
      continue;
    }
    const token = match[0];
    const restRaw = text.slice(token.length);
    if (restRaw !== "" && !/^\s/.test(restRaw)) {
      return Object.freeze({ kind: "attached", token, rest: restRaw });
    }
    return Object.freeze({
      kind: pattern.kind,
      token,
      rest: restRaw.trim(),
      match,
    });
  }
  return null;
}

// Conservative Task Card date grammar. An inline reason is the remainder
// after a complete recognized date token and whitespace; it is never parsed
// as further commands. Unrecognized input returns valid=false with no error
// so ordinary preset filtering can keep the query.
function resolveTypedSchedule(query, baseDate) {
  const text = String(query || "").trim();
  const start = getLocalDateStart(
    baseDate instanceof Date ? baseDate : new Date(),
  );
  if (!text) {
    return freezeTypedScheduleResult(null, "", false, null);
  }

  const prefix = matchTypedSchedulePrefix(text);
  if (!prefix) {
    return freezeTypedScheduleResult(null, "", false, null);
  }
  if (prefix.kind === "attached") {
    return freezeTypedScheduleResult(
      null,
      "",
      false,
      TYPED_SCHEDULE_ERROR_AMBIGUOUS,
    );
  }

  const reason = prefix.rest;
  if (prefix.kind === "iso") {
    const yearText = prefix.match[1];
    const monthText = prefix.match[2];
    const dayText = prefix.match[3];
    if (!isValidDateParts(yearText, monthText, dayText)) {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_INVALID,
      );
    }
    const resolved = typedScheduleDateOrError(
      new Date(
        parseIntegerText(yearText),
        parseIntegerText(monthText) - 1,
        parseIntegerText(dayText),
      ),
    );
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  if (prefix.kind === "month-day") {
    const resolved = parseTypedScheduleMonthDay(
      prefix.match[1],
      prefix.match[2],
      start,
    );
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  if (prefix.kind === "unit" || prefix.kind === "days") {
    const sign = prefix.match[1] || "";
    const countText = prefix.match[2];
    const unit = prefix.kind === "unit" ? prefix.match[3].toLowerCase() : "d";
    if (sign === "-") {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_NEGATIVE,
      );
    }
    if (prefix.kind === "days" && sign === "+") {
      return freezeTypedScheduleResult(
        null,
        reason,
        false,
        TYPED_SCHEDULE_ERROR_AMBIGUOUS,
      );
    }
    const parsedCount = parseTypedScheduleCount(countText);
    if (parsedCount.error) {
      return freezeTypedScheduleResult(null, reason, false, parsedCount.error);
    }
    const resolved = applyTypedScheduleUnit(start, parsedCount.count, unit);
    if (resolved.error) {
      return freezeTypedScheduleResult(null, reason, false, resolved.error);
    }
    return freezeTypedScheduleResult(resolved.date, reason, true, null);
  }

  const weekday =
    TYPED_SCHEDULE_WEEKDAY_INDEX[String(prefix.token || "").toLowerCase()];
  if (!Number.isInteger(weekday)) {
    return freezeTypedScheduleResult(
      null,
      reason,
      false,
      TYPED_SCHEDULE_ERROR_INVALID,
    );
  }
  const resolved = typedScheduleDateOrError(
    addLocalDateDays(start, getDaysUntilWeekday(start, weekday, false)),
  );
  if (resolved.error) {
    return freezeTypedScheduleResult(null, reason, false, resolved.error);
  }
  return freezeTypedScheduleResult(resolved.date, reason, true, null);
}

function createTypedScheduleValueItem(resolved, baseDate, currentValue) {
  if (!resolved) {
    return null;
  }
  const reason = String(resolved.reason || "");
  if (resolved.valid === true && resolved.date instanceof Date) {
    const date = getLocalDateStart(resolved.date);
    const value = formatBulletPropertyDate(date);
    const weekday = getBulletPropertyDateWeekday(date);
    const relative = formatRelativeDayOffset(
      getLocalDayOffset(baseDate, date),
    );
    const yearRollover =
      date.getFullYear() !== getLocalDateStart(baseDate).getFullYear();
    const label = `Use ${weekday} ${value}`;
    const detailParts = [relative];
    if (yearRollover) {
      detailParts.push(String(date.getFullYear()));
    }
    if (reason) {
      detailParts.push(reason);
    }
    return {
      kind: "value",
      value,
      label,
      detail: detailParts.join(" · "),
      current: value === currentValue,
      dynamic: true,
      typedSchedule: true,
      valid: true,
      inlineReason: reason,
      yearRollover,
      weekday,
      relative,
      searchText: `${label} ${detailParts.join(" ")}`,
    };
  }
  if (resolved.error) {
    return {
      kind: "value",
      value: "",
      label: "Invalid date",
      detail: resolved.error,
      current: false,
      dynamic: true,
      typedSchedule: true,
      valid: false,
      error: resolved.error,
      inlineReason: reason,
      searchText: `invalid date ${resolved.error}`,
    };
  }
  return null;
}

function getLocalTaskDependencyIdentifier(task, filePath = "") {
  if (!task) {
    return "";
  }
  if (task.existingBlockId && filePath) {
    return tryDependencyId(filePath, task.existingBlockId) || "";
  }
  return task.existingIdField || task.existingBlockId || "";
}

// ---- src/285-unblocked-notice.js ----
// Unblocked successor notice card (plan:202610/successor_offers.md §12.6,
// `nav_card`). Pure model plus the `bob-nh-notice is-unblock` fragment and
// the additive `api.notice` factory (v2 adds keep-moving rows, §12.15).
// Nothing here reads the vault; the cycler passes the shared snake_case
// notice model and this file renders it.
const UNBLOCKED_NOTICE_MAX_TEXT_LENGTH = 48;

const UNBLOCKED_NOTICE_NOT_LINKED_REASONS = Object.freeze({
  already_planned: "already planned",
  not_planned_today: "not planned today",
  breaker: "not linked · more than 5",
  not_selected: "not pulled in",
  no_destination: "no open Pomodoro",
  project_task: "project task",
  project_member: "project member",
  hidden: "hidden",
  disabled: "linking off",
  failed: "couldn't link",
  cancelled: "cancelled",
});

const UNBLOCKED_NOTICE_STATUS_NAMES = Object.freeze({
  " ": "Ready",
  "*": "Next",
  "/": "In Progress",
  "?": "Blocked",
});

const UNBLOCKED_NOTICE_MONTHS = Object.freeze([
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
]);

function truncateUnblockedText(text) {
  const source = String(text === null || text === undefined ? "" : text);
  if (source.length <= UNBLOCKED_NOTICE_MAX_TEXT_LENGTH) {
    return source;
  }
  return `${source.slice(0, UNBLOCKED_NOTICE_MAX_TEXT_LENGTH - 1).trimEnd()}…`;
}

function unblockedNoticeText(value) {
  return String(value === null || value === undefined ? "" : value).trim();
}

function unblockedNoticeList(value) {
  return Array.isArray(value) ? value : [];
}

function unblockedRowLane(row) {
  const named = unblockedNoticeText(row && row.status_name);
  if (named) {
    return named;
  }
  const symbol = row && row.status_symbol;
  if (typeof symbol === "string" && UNBLOCKED_NOTICE_STATUS_NAMES[symbol]) {
    return UNBLOCKED_NOTICE_STATUS_NAMES[symbol];
  }
  return "";
}

// Keep-moving rows (§12.15) name the lane a pick lands in. `/` is Pending
// here (never "In Progress"), and the raw symbol is never shown.
const KEEP_MOVING_LANE_BY_SYMBOL = Object.freeze({
  " ": "Ready",
  "*": "Next",
  "/": "Pending",
  "?": "Blocked",
});

function keepMovingRowLane(row) {
  const symbol = row && row.status_symbol;
  if (typeof symbol === "string" && KEEP_MOVING_LANE_BY_SYMBOL[symbol]) {
    return KEEP_MOVING_LANE_BY_SYMBOL[symbol];
  }
  const named = unblockedNoticeText(row && row.status_name);
  return named === "In Progress" ? "Pending" : named;
}

// ‹N› for a keep-moving row: the offer's project note, else the row's own
// note (a keep-moving row is always a resident of N).
function keepMovingProjectName(row) {
  const offer = row && row.offer && typeof row.offer === "object" ? row.offer : null;
  return (
    unblockedShortNoteName(offer && offer.project) ||
    unblockedShortNoteName(row && row.note_path) ||
    "project"
  );
}

function keepMovingProjectNames(rows) {
  const names = [];
  for (const row of rows) {
    const name = row.keepMovingProject || "project";
    if (!names.includes(name)) {
      names.push(name);
    }
  }
  return names;
}

// `keeps ‹N› moving` / `keeps 2 projects moving` (§12.15 copy table).
function keepMovingSuffix(rows) {
  const names = keepMovingProjectNames(rows);
  return names.length === 1
    ? `keeps ‹${names[0]}› moving`
    : `keeps ${names.length} projects moving`;
}

// `Keep ‹N› moving` / `Keep 2 projects moving`.
function keepMovingTitle(rows) {
  const names = keepMovingProjectNames(rows);
  return names.length === 1
    ? `Keep ‹${names[0]}› moving`
    : `Keep ${names.length} projects moving`;
}

// `2026-10-13` → `Oct 13`. Falls back to the raw text when it is not a
// plain ISO date, so a malformed fixture can never break the card.
function formatUnblockedScheduledDate(value) {
  const text = unblockedNoticeText(value);
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!match) {
    return text;
  }
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!Number.isInteger(month) || month < 1 || month > 12) {
    return text;
  }
  if (!Number.isInteger(day) || day < 1 || day > 31) {
    return text;
  }
  return `${UNBLOCKED_NOTICE_MONTHS[month - 1]} ${day}`;
}

function unblockedNoticeReasonText(notLinked) {
  const key = unblockedNoticeText(notLinked);
  if (!key) {
    return "";
  }
  if (UNBLOCKED_NOTICE_NOT_LINKED_REASONS[key]) {
    return UNBLOCKED_NOTICE_NOT_LINKED_REASONS[key];
  }
  return key;
}

function unblockedPredecessorPath(row, predecessors) {
  if (row && Array.isArray(row.unblocked_by) && row.unblocked_by.length > 0) {
    const first = unblockedNoticeText(row.unblocked_by[0] && row.unblocked_by[0].note_path);
    if (first) {
      return first;
    }
  }
  if (Array.isArray(predecessors) && predecessors.length > 0) {
    return unblockedNoticeText(predecessors[0] && predecessors[0].note_path);
  }
  return "";
}

function unblockedShortNoteName(notePath) {
  const path = unblockedNoticeText(notePath);
  if (!path) {
    return "";
  }
  const base = path.split("/").pop();
  return base.endsWith(".md") ? base.slice(0, -3) : base;
}

function unblockedPullInSummary(model, linked, recovered) {
  const source = model && (model.pull_in || model.pullIn);
  const hasCurrentReasons = recovered.some((row) =>
    ["not_selected", "no_destination"].includes(row.notLinked),
  );
  if ((!source || typeof source !== "object") && !hasCurrentReasons) {
    return null;
  }
  const offersValue = source && (
    source.offer_count ?? source.offerCount ??
    (typeof source.offers === "number" ? source.offers : undefined) ??
    (Array.isArray(source.offers) ? source.offers.length : undefined)
  );
  const offerCount = Number.isFinite(Number(offersValue))
    ? Math.max(0, Math.floor(Number(offersValue)))
    : Math.max(linked.length, recovered.filter((row) => row.notLinked === "not_selected").length + linked.length);
  const pulledIn = linked.length;
  const notPulledIn = Math.max(
    recovered.filter((row) => row.notLinked === "not_selected").length,
    offerCount - pulledIn,
  );
  const noDestination = recovered.filter((row) => row.notLinked === "no_destination").length;
  const destinations = [];
  for (const row of linked) {
    const name = unblockedEntryDisplayName(row.entryName);
    if (name && !destinations.includes(name)) destinations.push(name);
  }
  return Object.freeze({
    offerCount,
    pulledIn,
    notPulledIn,
    noDestination,
    destinations: Object.freeze(destinations),
    current: Boolean((source && source.supported === true) || hasCurrentReasons),
  });
}

function unblockedEntryDisplayName(entryName) {
  const name = unblockedNoticeText(entryName);
  return name || "today";
}

// ⏭ forms for a notice whose rows are all keep-moving picks (§12.15 copy
// table). Never uses 🔓 or the word "unblocked".
function keepMovingFallbackText(linked) {
  const suffix = keepMovingSuffix(linked);
  if (linked.length === 1) {
    const row = linked[0];
    const name = unblockedEntryDisplayName(row.entryName);
    if (row.entryCreated) {
      const nextUp = row.nextUp ? " (next up)" : "";
      return `⏭ Next in new ${name} session${nextUp}: ${truncateUnblockedText(row.text)} · ${suffix}`;
    }
    return `⏭ Next in ${name}: ${truncateUnblockedText(row.text)} · ${suffix}`;
  }
  const names = [];
  for (const row of linked) {
    const name = unblockedEntryDisplayName(row.entryName);
    if (!names.includes(name)) {
      names.push(name);
    }
  }
  return names.length === 1
    ? `⏭ ${linked.length} linked → ${names[0]} · ${suffix}`
    : `⏭ ${linked.length} linked · ${names.join(", ")} · ${suffix}`;
}

// Plain-text fallback and card aria-label. Follows the §12.6 notice-text
// table: one linked, several linked (one entry / several entries), created
// continuation, breaker, recovered-only, and partial failure.
function unblockedFallbackText(summary) {
  const linked = summary.linked || [];
  const recovered = summary.recovered || [];
  const predecessors = summary.predecessors || [];
  const predText =
    predecessors.length === 1
      ? truncateUnblockedText(predecessors[0].text || "")
      : predecessors.length > 1
        ? `${predecessors.length} tasks`
        : "task";
  if (summary.failure) {
    const count = summary.failure.count;
    const reason = unblockedNoticeText(summary.failure.reason);
    const noun = count === 1 ? "successor" : "successors";
    return `⚠ Closed ${predText} — couldn't link ${count} ${noun}${reason ? ` (${reason})` : ""}`;
  }
  if (summary.onlyKeepMoving && linked.length > 0) {
    return keepMovingFallbackText(linked);
  }
  if (summary.onlyRelation) {
    return relationNoticeFallbackText(
      summary.relationLinked,
      summary.relationHeld,
      summary.relationUncertainty,
    ) || "🪢";
  }
  if (summary.pullIn && summary.pullIn.current) {
    const destinationText = summary.pullIn.destinations.length > 0
      ? ` → ${summary.pullIn.destinations.join(", ")}`
      : "";
    const notPulled = summary.pullIn.notPulledIn > 0
      ? ` · ${summary.pullIn.notPulledIn} not pulled in`
      : "";
    const noDestination = summary.pullIn.noDestination > 0
      ? ` · ${summary.pullIn.noDestination} no open Pomodoro${summary.pullIn.noDestination === 1 ? "" : "s"}`
      : "";
    return `🔓 ${summary.pullIn.pulledIn} pulled in${notPulled}${noDestination}${destinationText}`;
  }
  if (summary.isBreaker) {
    return `🔓 ${summary.total} unblocked · not linked (more than 5)`;
  }
  if (linked.length === 1) {
    const row = linked[0];
    const name = unblockedEntryDisplayName(row.entryName);
    const projectEmpty = row.projectEmpty ? " · project has no open tasks" : "";
    if (row.entryCreated) {
      const nextUp = row.nextUp ? " (next up)" : "";
      return `🔓 Next in new ${name} session${nextUp}: ${truncateUnblockedText(row.text)}${projectEmpty}`;
    }
    return `🔓 Next in ${name}: ${truncateUnblockedText(row.text)}${projectEmpty}`;
  }
  if (linked.length > 1) {
    const names = [];
    for (const row of linked) {
      const name = unblockedEntryDisplayName(row.entryName);
      if (!names.includes(name)) {
        names.push(name);
      }
    }
    if (names.length === 1) {
      const texts = linked
        .slice(0, 2)
        .map((row) => truncateUnblockedText(row.text));
      const tail = linked.length > 2 ? `, +${linked.length - 2}` : "";
      const projectEmpty = linked.every((row) => row.projectEmpty)
        ? " · project has no open tasks"
        : "";
      return `🔓 ${linked.length} linked → ${names[0]}: ${texts.join(", ")}${tail}${projectEmpty}`;
    }
    const projectEmpty = linked.every((row) => row.projectEmpty)
      ? " · project has no open tasks"
      : "";
    return `🔓 ${linked.length} linked · ${names.join(", ")}${projectEmpty}`;
  }
  if (recovered.length > 0) {
    const first = recovered[0];
    const lane = unblockedNoticeText(first.lane);
    const projectRows = recovered.filter((row) => row.projectEmpty);
    if (
      projectRows.length === 1 &&
      first.hideRemoved &&
      first.previousStatusSymbol === first.statusSymbol
    ) {
      return `🔓 Surfaced: ${truncateUnblockedText(first.text)}${lane ? ` (${lane})` : ""} · project has no open tasks`;
    }
    const projectEmpty = first.projectEmpty ? " · project has no open tasks" : "";
    return `🔓 Unblocked: ${truncateUnblockedText(first.text)}${lane ? ` (${lane})` : ""}${projectEmpty}`;
  }
  return "🔓 Unblocked";
}

// Validates and normalizes the shared §12.5 notice model. Returns a frozen
// view, or null when there is nothing to show (no unblocked rows and no
// failure). Never throws.
function buildUnblockedNoticeModel(model, options = {}) {
  try {
    if (!model || typeof model !== "object") {
      return null;
    }
    const predecessors = unblockedNoticeList(model.predecessors)
      .map((entry) => ({
        note_path: unblockedNoticeText(entry && entry.note_path),
        block_id: unblockedNoticeText(entry && entry.block_id),
        text: unblockedNoticeText(entry && entry.text),
      }))
      .filter((entry) => entry.text);
    const unblocked = unblockedNoticeList(model.unblocked).filter(
      (row) => row && typeof row === "object",
    );
    const stillBlocked = unblockedNoticeList(model.still_blocked).filter(
      (row) => row && typeof row === "object",
    );
    const failure =
      model.failure && typeof model.failure === "object"
        ? {
            count: Math.max(
              0,
              Math.floor(numericOrDefault(model.failure.count, 0)),
            ),
            reason: unblockedNoticeText(model.failure.reason),
          }
        : null;
    const hasFailure = failure !== null && failure.count > 0;
    const hasProjectStillBlocked = stillBlocked.some(
      (row) => unblockedNoticeText(row.trigger) === "project_empty",
    );
    // Keep-moving rows (notice v2, §12.15) arrive in their own array. Only
    // picked rows (with a `link`) are reported: an unpicked keep-moving offer
    // recovered nothing, so it stays silent.
    const keepMovingSource = unblockedNoticeList(model.keep_moving).filter(
      (row) => row && typeof row === "object" && row.link && typeof row.link === "object",
    );
    const relationSource = collectRelationNoticeRows(model);
    const relationHeldSource = collectRelationHeldRows(model);
    const relationUncertainty = relationNoticeUncertaintyLine(model);
    if (
      unblocked.length === 0 &&
      keepMovingSource.length === 0 &&
      relationSource.length === 0 &&
      relationHeldSource.length === 0 &&
      !relationUncertainty &&
      !hasFailure &&
      !hasProjectStillBlocked
    ) {
      return null;
    }
    const dailyPath = unblockedNoticeText(model.daily_path);
    const dailyContent =
      typeof model.daily_content === "string" ? model.daily_content : null;

    const linked = [];
    const recovered = [];
    for (const row of unblocked) {
      const link =
        row.link && typeof row.link === "object" ? row.link : null;
      const base = {
        note_path: unblockedNoticeText(row.note_path),
        block_id: unblockedNoticeText(row.block_id),
        text: truncateUnblockedText(row.text),
        fullText: unblockedNoticeText(row.text),
        inbox: row.inbox === true,
        lane: unblockedRowLane(row),
        trigger: unblockedNoticeText(row.trigger),
        projectEmpty: unblockedNoticeText(row.trigger) === "project_empty",
        previousStatusSymbol: unblockedNoticeText(row.previous_status_symbol),
        statusSymbol: unblockedNoticeText(row.status_symbol),
        hideRemoved: row.hide_removed === true,
      };
      if (link) {
        linked.push(
          Object.freeze({
            ...base,
            entryName: unblockedNoticeText(link.entry_name),
            entryCreated: link.entry_created === true,
            nextUp: link.next_up === true,
            blockIdCreated: link.block_id_created === true,
            blockLink: unblockedNoticeText(link.block_link),
          }),
        );
      } else {
        recovered.push(
          Object.freeze({
            ...base,
            notLinked: unblockedNoticeText(row.not_linked),
            reason: unblockedNoticeReasonText(row.not_linked),
          }),
        );
      }
    }
    const keepMoving = keepMovingSource.map((row) => {
      const link = row.link;
      return Object.freeze({
        note_path: unblockedNoticeText(row.note_path),
        block_id: unblockedNoticeText(row.block_id),
        text: truncateUnblockedText(row.text),
        fullText: unblockedNoticeText(row.text),
        inbox: row.inbox === true,
        lane: keepMovingRowLane(row),
        trigger: "last_planned",
        projectEmpty: false,
        keepMoving: true,
        keepMovingProject: keepMovingProjectName(row),
        previousStatusSymbol: unblockedNoticeText(row.previous_status_symbol),
        statusSymbol: unblockedNoticeText(row.status_symbol),
        hideRemoved: false,
        entryName: unblockedNoticeText(link.entry_name),
        entryCreated: link.entry_created === true,
        nextUp: link.next_up === true,
        blockIdCreated: link.block_id_created === true,
        blockLink: unblockedNoticeText(link.block_link),
      });
    });

    const still = stillBlocked.map((row) => {
      const waitsOn = Math.max(
        0,
        Math.floor(numericOrDefault(row.waits_on, 0)),
      );
      const reason = unblockedNoticeText(row.reason);
      const scheduled = unblockedNoticeText(row.scheduled);
      const projectEmpty = unblockedNoticeText(row.trigger) === "project_empty";
      let reasonSuffix = "";
      if (["project", "project_dependency", "project_schedule"].includes(reason)) {
        reasonSuffix = scheduled
          ? `· project until ${formatUnblockedScheduledDate(scheduled)}`
          : "· blocked by project";
      } else if (reason === "scheduled" && scheduled) {
        reasonSuffix = `· waits until ${formatUnblockedScheduledDate(scheduled)}`;
      } else {
        reasonSuffix = `· waits on ${waitsOn} more`;
      }
      const suffix = `${projectEmpty ? "· no open tasks " : ""}${reasonSuffix}`;
      return Object.freeze({
        note_path: unblockedNoticeText(row.note_path),
        block_id: unblockedNoticeText(row.block_id),
        text: truncateUnblockedText(row.text),
        fullText: unblockedNoticeText(row.text),
        inbox: row.inbox === true,
        trigger: unblockedNoticeText(row.trigger),
        projectEmpty,
        suffix,
      });
    });

    const relationLinked = relationSource.map(mapRelationNoticeLinkedRow);
    const relationHeld = relationHeldSource.map((row) =>
      mapRelationHeldNoticeRow(row, formatUnblockedScheduledDate(row.scheduled)),
    );
    // Keep-moving and relation picks count as linked in every summary.
    const allLinked = [...linked, ...relationLinked, ...keepMoving];
    const onlyKeepMoving =
      keepMoving.length > 0 &&
      linked.length === 0 &&
      relationLinked.length === 0 &&
      recovered.length === 0 &&
      stillBlocked.length === 0;
    const onlyRelation =
      (relationLinked.length > 0 || relationHeld.length > 0 || Boolean(relationUncertainty)) &&
      keepMoving.length === 0 &&
      linked.length === 0 &&
      recovered.length === 0 &&
      stillBlocked.length === 0;
    const breakerCount = recovered.filter(
      (row) => row.notLinked === "breaker",
    ).length;
    const isBreaker =
      allLinked.length === 0 &&
      recovered.length > 0 &&
      breakerCount === recovered.length;

    const pullIn = unblockedPullInSummary(model, allLinked, recovered);

    const total = unblocked.length + still.length;
    // Relation picks count as linked; keep-moving rows render last (§12.15, §12.18).
    const ordered = Object.freeze([
      ...linked.map((row) => ({ kind: "linked", row })),
      ...relationLinked.map((row) => ({ kind: "linked", row })),
      ...recovered.map((row) => ({ kind: "recovered", row })),
      ...still.map((row) => ({ kind: "stillBlocked", row })),
      ...keepMoving.map((row) => ({ kind: "linked", row })),
    ]);
    const visibleRows = ordered.slice(0, 3);
    const moreCount = Math.max(0, ordered.length - visibleRows.length);

    let countPill = "";
    if (pullIn && pullIn.current && !onlyKeepMoving && !onlyRelation) {
      const destinationText = pullIn.destinations.length > 0
        ? ` → ${pullIn.destinations.join(", ")}`
        : "";
      const noDestination = pullIn.noDestination > 0
        ? ` · ${pullIn.noDestination} no open Pomodoro${pullIn.noDestination === 1 ? "" : "s"}`
        : "";
      countPill = `${pullIn.pulledIn} pulled in${pullIn.notPulledIn > 0 ? ` · ${pullIn.notPulledIn} not pulled in` : ""}${noDestination}${destinationText}`;
    } else if (isBreaker) {
      countPill = `${unblocked.length} · not linked`;
    } else if (allLinked.length > 0) {
      const names = [];
      for (const row of allLinked) {
        const name = unblockedEntryDisplayName(row.entryName);
        if (!names.includes(name)) {
          names.push(name);
        }
      }
      const created = allLinked.some((row) => row.entryCreated);
      if (names.length === 1) {
        countPill = created
          ? `${allLinked.length} → new ${names[0]} session`
          : `${allLinked.length} → ${names[0]}`;
      } else {
        countPill = `${allLinked.length} linked`;
      }
      if (allLinked.some((row) => row.nextUp)) {
        countPill += " · next up";
      }
    } else if (unblocked.length > 0) {
      countPill = `${unblocked.length}`;
    }

    const defaultReceipt = predecessors.length === 1
      ? `✓ ${truncateUnblockedText(predecessors[0].text)}`
      : predecessors.length > 1 ? `✓ ${predecessors.length} tasks` : "✓ done";
    const receipt = onlyRelation
      ? relationNoticeReceiptFromRows(relationLinked, relationHeld, predecessors) || defaultReceipt
      : defaultReceipt;

    const app =
      options && typeof options === "object" ? options.app : undefined;
    let planChip = "";
    try {
      planChip =
        typeof dailyContent === "string"
          ? getCancelPlanBudgetChip(app, dailyContent)
          : "";
    } catch (error) {
      planChip = "";
    }
    const minted = allLinked.filter((row) => row.blockIdCreated);
    let addedChip = "";
    if (minted.length === 1 && minted[0].block_id) {
      addedChip = `added ^${minted[0].block_id}`;
    } else if (minted.length > 1) {
      addedChip = `added ${minted.length} block IDs`;
    }
    const chips = [];
    if (planChip) {
      chips.push(Object.freeze({ text: planChip, tone: "info" }));
    }
    if (addedChip) {
      chips.push(Object.freeze({ text: addedChip, tone: "ok" }));
    }
    if (allLinked.length > 0) {
      chips.push(Object.freeze({ text: "Alt+N releases", tone: "muted" }));
    }

    const summary = {
      linked: allLinked,
      onlyKeepMoving,
      onlyRelation,
      relationLinked,
      relationHeld,
      relationUncertainty,
      recovered,
      predecessors,
      pullIn,
      failure: hasFailure ? failure : null,
      isBreaker,
      showLegacyBreaker: isBreaker && !(pullIn && pullIn.current),
      total: unblocked.length,
    };
    const text = unblockedFallbackText(summary);
    const durationMs = Math.min(
      10000,
      6000 + 1000 * Math.max(0, Math.min(3, ordered.length) - 1),
    );
    return Object.freeze({
      predecessors: Object.freeze(predecessors),
      linked: Object.freeze(linked),
      recovered: Object.freeze(recovered),
      stillBlocked: Object.freeze(still),
      rows: ordered,
      visibleRows: Object.freeze(visibleRows),
      moreCount,
      isBreaker,
      pullIn,
      keepMoving: Object.freeze(keepMoving),
      keepMovingOnly: onlyKeepMoving,
      relationLinked: Object.freeze(relationLinked),
      relationHeld: Object.freeze(relationHeld),
      relationOnly: onlyRelation,
      relationUncertainty,
      glyph: onlyRelation ? RELATION_COPY_GLYPH : onlyKeepMoving ? "⏭" : "🔓",
      showLegacyBreaker: isBreaker && !(pullIn && pullIn.current),
      failure: hasFailure ? Object.freeze(failure) : null,
      dailyPath,
      countPill,
      receipt,
      chips: Object.freeze(chips),
      text,
      title: onlyRelation
        ? relationNoticeTitleFromRows(relationLinked, relationHeld) || "Relation"
        : onlyKeepMoving
          ? keepMovingTitle(keepMoving)
          : ordered.length > 0 && ordered.every((entry) => entry.row.projectEmpty)
            ? "Project empty"
            : "Unblocked",
      durationMs,
    });
  } catch (error) {
    return null;
  }
}

async function openUnblockedRowTarget(app, row, dailyPath) {
  try {
    const workspace = app && app.workspace;
    if (!workspace || typeof workspace.openLinkText !== "function") {
      return false;
    }
    const notePath = unblockedNoticeText(row && row.note_path);
    if (!notePath) {
      return false;
    }
    const blockId = unblockedNoticeText(row && row.block_id);
    const linkText = blockId ? `${notePath}#^${blockId}` : notePath;
    const targetFile =
      app.vault && typeof app.vault.getAbstractFileByPath === "function"
        ? app.vault.getAbstractFileByPath(notePath)
        : null;
    const leaf = workspace.activeLeaf || workspace.getLeaf(false);
    if (!targetFile || !leaf) {
      return false;
    }
    const sourcePath = unblockedNoticeText(dailyPath);
    return await openWithLeafSwitchGuard(app, targetFile, leaf, () =>
      workspace.openLinkText(linkText, sourcePath || ""),
    );
  } catch (error) {
    return false;
  }
}

function attachUnblockedRowClick(rowEl, handler) {
  try {
    if (!rowEl || typeof handler !== "function") {
      return;
    }
    rowEl.unblockedClick = handler;
    if (typeof rowEl.addEventListener === "function") {
      rowEl.addEventListener("click", (event) => {
        try {
          if (
            event &&
            typeof event.stopPropagation === "function"
          ) {
            event.stopPropagation();
          }
        } catch (error) {
          // A click must never fail on propagation.
        }
        return handler(event);
      });
    }
  } catch (error) {
    // Click wiring never breaks rendering.
  }
}

function renderUnblockedNoticeFragment(view, root, options = {}) {
  const settings =
    options && typeof options === "object" ? options : {};
  let model = view;
  if (
    model &&
    typeof model === "object" &&
    !Array.isArray(model.rows) &&
    Array.isArray(model.unblocked)
  ) {
    model = buildUnblockedNoticeModel(model, settings);
  }
  if (!model || typeof model !== "object" || !Array.isArray(model.rows)) {
    return null;
  }
  const app = settings.app;
  const keepMovingOnly = model.keepMovingOnly === true;
  const relationOnly = model.relationOnly === true;
  const card = root.createDiv({
    cls: `bob-nh-notice is-unblock${keepMovingOnly ? " is-keep-moving" : ""}${relationOnly ? " is-relation" : ""}`,
    attr: { "aria-label": model.text },
  });
  const headerEl = card.createDiv({ cls: "bob-nh-notice-header" });
  const iconEl = headerEl.createSpan({ cls: "bob-nh-notice-icon" });
  iconEl.createSpan({
    cls: "bob-nh-notice-glyph",
    text: model.glyph || (keepMovingOnly ? "⏭" : "🔓"),
    attr: { "aria-hidden": "true" },
  });
  headerEl.createSpan({ cls: "bob-nh-notice-level", text: model.title || "Unblocked" });
  if (model.countPill) {
    headerEl.createSpan({
      cls: "bob-nh-notice-count",
      text: model.countPill,
    });
  }
  headerEl.createSpan({
    cls: "bob-nh-notice-receipt",
    text: model.receipt,
  });

  if (model.showLegacyBreaker === true || (model.showLegacyBreaker === undefined && model.isBreaker)) {
    const reasonEl = card.createDiv({ cls: "bob-nh-notice-reason" });
    reasonEl.createSpan({
      cls: "bob-nh-notice-reason-text",
      text: "More than 5 at once — link the ones you want with Ctrl+Shift+Enter",
    });
  }

  if (Array.isArray(model.visibleRows) && model.visibleRows.length > 0) {
    const rowsEl = card.createDiv({ cls: "bob-nh-unblock-rows" });
    for (const entry of model.visibleRows) {
      const kind = entry && entry.kind;
      const row = entry && entry.row;
      if (!row) {
        continue;
      }
      if (kind === "linked") {
        const rowEl = rowsEl.createDiv({
          cls: `bob-nh-unblock-row is-linked is-clickable${row.keepMoving ? " is-keep-moving" : ""}${row.relation ? " is-relation" : ""}`,
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-glyph",
          text: "＋",
          attr: { "aria-hidden": "true" },
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-text",
          text: row.text,
        });
        if (row.lane) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-ok",
            text: row.lane,
          });
        }
        if (row.projectEmpty) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: "no open tasks",
          });
        }
        if (row.keepMoving && !keepMovingOnly) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-keep-moving",
            text: keepMovingSuffix([row]),
          });
        }
        if (row.relation && !relationOnly) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-relation",
            text: relationCopyChip(row.relationLabel, row.relationTarget),
          });
        }
        const extra = [];
        const firstPred = unblockedPredecessorPath(
          { note_path: row.note_path, unblocked_by: [] },
          model.predecessors,
        );
        if (row.note_path && firstPred && row.note_path !== firstPred) {
          extra.push(`↗ ${unblockedShortNoteName(row.note_path)}`);
        }
        if (row.inbox) {
          extra.push("inbox");
        }
        if (row.entryCreated || row.nextUp) {
          const name = unblockedEntryDisplayName(row.entryName);
          extra.push(
            row.entryCreated
              ? `→ new ${name}${row.nextUp ? " · next up" : ""}`
              : `→ ${name}${row.nextUp ? " · next up" : ""}`,
          );
        }
        for (const chip of extra) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: chip,
          });
        }
        const target = { note_path: row.note_path, block_id: row.block_id };
        const dailyPath = model.dailyPath;
        attachUnblockedRowClick(rowEl, () =>
          openUnblockedRowTarget(app, target, dailyPath),
        );
      } else if (kind === "recovered") {
        const rowEl = rowsEl.createDiv({
          cls: "bob-nh-unblock-row is-muted is-clickable",
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-glyph",
          text: "🔓",
          attr: { "aria-hidden": "true" },
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-text",
          text: row.text,
        });
        if (row.lane) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: row.lane,
          });
        }
        if (row.projectEmpty) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: "no open tasks",
          });
        }
        if (row.reason) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: row.reason,
          });
        }
        if (row.inbox) {
          rowEl.createSpan({
            cls: "bob-nh-notice-chip is-muted",
            text: "inbox",
          });
        }
        const target = { note_path: row.note_path, block_id: row.block_id };
        const dailyPath = model.dailyPath;
        attachUnblockedRowClick(rowEl, () =>
          openUnblockedRowTarget(app, target, dailyPath),
        );
      } else {
        const rowEl = rowsEl.createDiv({
          cls: "bob-nh-unblock-row is-muted",
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-glyph",
          text: "🔒",
          attr: { "aria-hidden": "true" },
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-text",
          text: row.text,
        });
        rowEl.createSpan({
          cls: "bob-nh-unblock-suffix",
          text: row.suffix,
        });
      }
    }
    if (model.moreCount > 0) {
      rowsEl.createDiv({
        cls: "bob-nh-unblock-more",
        text: `+${model.moreCount} more`,
      });
    }
  }

  const mutedRelation = relationOnly && model.relationHeld && model.relationHeld[0] &&
    !(model.visibleRows && model.visibleRows.length)
    ? model.relationHeld[0].notice : "";
  for (const text of [mutedRelation, model.relationUncertainty].filter(Boolean)) {
    card.createDiv({ cls: "bob-nh-notice-reason" }).createSpan({
      cls: "bob-nh-notice-reason-text",
      text,
    });
  }

  if (model.failure) {
    const failureEl = card.createDiv({ cls: "bob-nh-notice-reason" });
    const count = model.failure.count;
    const noun = count === 1 ? "successor" : "successors";
    const reason = model.failure.reason
      ? ` (${model.failure.reason})`
      : "";
    failureEl.createSpan({
      cls: "bob-nh-notice-reason-text",
      text: `⚠ Couldn't link ${count} ${noun}${reason}`,
    });
  }

  if (Array.isArray(model.chips) && model.chips.length > 0) {
    const chipsEl = card.createDiv({ cls: "bob-nh-notice-chips" });
    for (const chip of model.chips) {
      chipsEl.createSpan({
        cls: `bob-nh-notice-chip is-${chip.tone}`,
        text: chip.text,
      });
    }
  }

  return card;
}

function showUnblockedNotice(app, model, options = {}) {
  const settings =
    options && typeof options === "object" ? options : {};
  const view = buildUnblockedNoticeModel(model, { app });
  if (!view) {
    return false;
  }
  const fallbackText =
    typeof view.text === "string" ? view.text : "🔓 Unblocked";
  const noticeOptions = { ...settings, app, duration: view.durationMs };
  try {
    if (typeof document === "undefined") {
      showBulletPropertyNotice(fallbackText, noticeOptions);
      return true;
    }
    const fragment = document.createDocumentFragment();
    if (!fragment || typeof fragment.createDiv !== "function") {
      showBulletPropertyNotice(fallbackText, noticeOptions);
      return true;
    }
    const card = renderUnblockedNoticeFragment(view, fragment, { app });
    if (!card) {
      showBulletPropertyNotice(fallbackText, noticeOptions);
      return true;
    }
    showBulletPropertyNotice(fragment, noticeOptions);
    return true;
  } catch (error) {
    try {
      showBulletPropertyNotice(fallbackText, noticeOptions);
      return true;
    } catch (fallbackError) {
      return false;
    }
  }
}

// Additive `api.notice` factory (v3: `keep_moving` plus `relation_successors`,
// §12.13/§12.18). Kept here (rather than inline in 480) so
// `480-review-jump-and-nav-api.js` stays under the 1000-line fragment limit.
// The api itself stays `version: 3`; this member carries its own version like
// `reviewWalk`. v6 reads req_outcomes/req_met; older payloads render as before.
function createNoticeApi(plugin) {
  const app =
    plugin && typeof plugin === "object" ? plugin.app : undefined;
  return Object.freeze({
    version: 6,
    showUnblocked: (model) => showUnblockedNotice(app, { ...model, __noticePlugin: plugin }),
  });
}
// ---- src/290-local-task-items.js ----
function createBulletPropertyLocalTaskItems(content, options = {}) {
  const dependencyValues =
    options.dependencyValues instanceof Set
      ? options.dependencyValues
      : new Set(options.dependencyValues || []);
  const dependencyValueSets = Array.isArray(options.dependencyValueSets)
    ? options.dependencyValueSets.map((values) =>
        values instanceof Set ? values : new Set(values || []),
      )
    : [dependencyValues];

  return getOpenLocalTasks(content, {
    excludeLine: options.excludeLine,
    excludeLines: options.excludeLines,
  }).map(
    (task) => {
      // The dependency value stored in `[dependsOn:: ...]` (prefers an existing
      // `[id::]`, then the trailing block ID). The link block ID is the trailing
      // `^block-id` the navigation bullet points at, which may be absent even
      // when a dependency value exists.
      const dependencyValue = getLocalTaskDependencyIdentifier(
        task,
        options.filePath || "",
      );
      const legacyDependencyValue = task.existingIdField || task.existingBlockId || "";
      const linkBlockId = task.existingBlockId || "";
      const linkedSourceCount = dependencyValue
        ? dependencyValueSets.filter(
            (values) =>
              values.has(dependencyValue) ||
              (legacyDependencyValue !== dependencyValue &&
                values.has(legacyDependencyValue)),
          ).length
        : 0;
      const linkState =
        linkedSourceCount === 0
          ? "none"
          : linkedSourceCount === dependencyValueSets.length
            ? "all"
            : "mixed";
      const alreadyLinked = linkState === "all";
      const needsBlockIdPrompt = !linkBlockId;
      const needsDependencyValue = !dependencyValue;
      const needsPromptForAdd = !alreadyLinked && needsBlockIdPrompt;

      return Object.freeze({
        kind: "local-task",
        ...task,
        value: dependencyValue,
        dependencyValue,
        legacyDependencyValue,
        linkBlockId,
        alreadyLinked,
        linkedSourceCount,
        sourceCount: dependencyValueSets.length,
        linkState,
        needsBlockIdPrompt,
        needsDependencyValue,
        needsPromptForAdd,
        searchText: [
          task.displayText,
          `line ${task.line + 1}`,
          task.status,
          dependencyValue,
          alreadyLinked ? "depends linked" : "",
          linkState === "mixed" ? "mixed partially linked" : "",
          needsPromptForAdd
            ? "needs id block create"
            : dependencyValue
              ? "block id"
              : "create id",
        ]
          .filter(Boolean)
          .join(" "),
      });
    },
  );
}

// ---------- Vault-wide Depends on stage (nav-stage) ----------
// `docs/task-dependencies.md` §6 in bob-cli is authoritative: the candidate
// pool is vault-wide (Tasks cache with open-buffer overrides, falling back
// to a one-time vault scan), ranking ports `capture_link_tasks.rs::rank`,
// and rows group into CURRENT / RESULTS / BLOCKED with guards. Every helper
// here is pure and synchronous so the stage never reads from disk on a
// keystroke; the plugin methods below supply the pool and the commit path.
const DEPENDENCY_STAGE_MAX_ROWS = 60;
const DEPENDENCY_STAGE_SECTION_RE = /^#{1,6}\s+(.*?)\s*#*\s*$/;

// Identity key for one stage row or graph node: the NUL separator keeps
// paths with spaces unambiguous (block ids never contain whitespace).
function dependencyStageRowKey(path, blockId) {
  const normalized = normalizeVaultRelativePath(path || "");
  const id = normalizeBulletPropertyValue(blockId || "");
  if (!normalized || !id) {
    return null;
  }
  return `${normalized}\x00${id}`;
}

// One tier check, ported from `field_tier` in
// `src/native/capture_link_tasks.rs`: 3 for a field prefix, 2 for a word
// prefix (the preceding character is not alphanumeric), 1 for a substring,
// and 0 for an in-order subsequence. Both sides are already lowercased.
function dependencyStageFieldTier(field, term) {
  const text = String(field || "");
  const needle = String(term || "");
  if (!needle) {
    return null;
  }
  if (text.startsWith(needle)) {
    return 3;
  }
  let from = text.indexOf(needle, 1);
  while (from !== -1) {
    const before = text[from - 1];
    if (before !== undefined && !/[\p{L}\p{N}]/u.test(before)) {
      return 2;
    }
    from = text.indexOf(needle, from + 1);
  }
  if (text.includes(needle)) {
    return 1;
  }
  let wanted = 0;
  for (const cell of text) {
    if (cell === needle[wanted]) {
      wanted += 1;
      if (wanted >= needle.length) {
        return 0;
      }
    }
  }
  return null;
}

// A term's best tier over the searchable fields, or null when it matches
// nothing: the cleaned description, `route:blockId`, the block id, the note
// route, and the section heading (`docs/task-dependencies.md` §6.3).
function dependencyStageTermTier(candidate, term) {
  const needle = String(term || "").toLowerCase();
  if (!needle || !candidate) {
    return null;
  }
  const fields = [];
  if (candidate.blockId) {
    fields.push(`${candidate.route || ""}:${candidate.blockId}`);
    fields.push(candidate.blockId);
  }
  fields.push(candidate.text || "");
  fields.push(candidate.route || "");
  if (candidate.section) {
    fields.push(candidate.section);
  }
  let best = null;
  for (const field of fields) {
    const tier = dependencyStageFieldTier(
      String(field || "").toLowerCase(),
      needle,
    );
    if (tier !== null && (best === null || tier > best)) {
      best = tier;
    }
  }
  return best;
}

// Every candidate matching a query, paired with its summed tier score,
// ported from `match_score` in `src/native/capture_link_tasks.rs`: every
// whitespace-separated term must match, and the result keeps input order.
// An empty query matches every candidate with score 0.
function dependencyStageScoredMatches(candidates, query) {
  const list = Array.isArray(candidates) ? candidates : [];
  const terms = String(query || "")
    .split(/\s+/)
    .map((term) => term.toLowerCase())
    .filter(Boolean);
  const scored = [];
  for (const candidate of list) {
    let score = 0;
    let matched = true;
    for (const term of terms) {
      const tier = dependencyStageTermTier(candidate, term);
      if (tier === null) {
        matched = false;
        break;
      }
      score += tier;
    }
    if (matched) {
      scored.push({ candidate, score });
    }
  }
  return scored;
}

// Rank candidates for a query, ported from `rank` in
// `src/native/capture_link_tasks.rs`: tasks order by the summed tiers
// descending, and ties (and the empty query) keep the input order. The sort
// is stable, so callers pre-sort into canonical order first.
function dependencyStageRank(candidates, query) {
  return dependencyStageScoredMatches(candidates, query)
    .sort((left, right) => right.score - left.score)
    .map((entry) => entry.candidate);
}

// A stage's matches in display order: match score always leads, and
// `tieCompare` (status, then the stage's canonical order) only orders
// candidates whose scores are equal, including every row of an empty query.
function orderDependencyStageMatches(candidates, query, tieCompare) {
  return dependencyStageScoredMatches(candidates, query)
    .sort(
      (left, right) =>
        right.score - left.score ||
        tieCompare(left.candidate, right.candidate),
    )
    .map((entry) => entry.candidate);
}

// Section headers for one merged stage list, given each row's status class
// (`"results"`, `"blocked"`, or `"closed"`): a typed query heads only its
// first ranked row with RESULTS, whatever that row's status. An empty filter
// ties every score, so each status class heads its own first row.
function dependencyStageHeaderSections(statusClasses, emptyQuery) {
  const seen = new Set();
  return statusClasses.map((statusClass, index) => {
    if (!emptyQuery) {
      return index === 0 ? "results" : null;
    }
    if (seen.has(statusClass)) {
      return null;
    }
    seen.add(statusClass);
    return statusClass;
  });
}

function dependencyStageRouteOf(path) {
  return String(path || "").replace(/\.md$/i, "");
}

function dependencyStageBasenameOf(path) {
  const route = dependencyStageRouteOf(path);
  const at = route.lastIndexOf("/");
  return at === -1 ? route : route.slice(at + 1);
}

// RESULTS exclusions (`docs/task-dependencies.md` §6.2): daily notes
// (`YYYY/YYYYMMDD.md`), `done/`, `_templates`, `_generated`, `_conflicts`
// (matched as a path segment), dot-dirs, and the dependent itself (handled
// by the caller through `dependentLines`). Fenced code never reaches here:
// the task scanner skips it.
function isDependencyStageExcludedPath(path) {
  const normalized = String(path || "").replace(/\\/g, "");
  if (!normalized || isUnsafeVaultPath(normalized)) {
    return true;
  }
  if (/^\d{4}\/\d{8}\.md$/i.test(normalized)) {
    return true;
  }
  const segments = normalized.split("/");
  if (
    segments.some(
      (segment) =>
        segment.startsWith(".") ||
        segment === "_templates" ||
        segment === "_generated" ||
        segment === "_conflicts",
    )
  ) {
    return true;
  }
  return isDoneArchivePath(normalized);
}

function findDependencyStageSection(lines, line) {
  const sourceLines = Array.isArray(lines) ? lines : [];
  for (let index = line - 1; index >= 0; index -= 1) {
    const match = DEPENDENCY_STAGE_SECTION_RE.exec(
      String(sourceLines[index] || ""),
    );
    if (match) {
      return (match[1] || "").trim() || null;
    }
  }
  return null;
}

// Every `#task` line in one note, open or closed, plus non-task block-id
// carriers (for the "not a task" CURRENT state). Fenced code and frontmatter
// are skipped through the shared line contexts. Sections are carried forward
// during the single scan instead of searching backward per task.
function scanDependencyStageNoteTasks(content) {
  return createDependencyNoteSnapshot(content).entries;
}

function createDependencySnapshotMap(notes) {
  const snapshots = new Map();
  for (const note of Array.isArray(notes) ? notes : []) {
    if (!note) {
      continue;
    }
    const path = normalizeVaultRelativePath(note.path || "");
    if (!path) {
      continue;
    }
    if (!snapshots.has(path)) {
      snapshots.set(path, createDependencyNoteSnapshot(note.content));
    } else {
      snapshots.set(path, createDependencyNoteSnapshot(note.content));
    }
  }
  return snapshots;
}

function collectVaultDependencyCandidatesFromSnapshots(snapshots, options = {}) {
  const dependentPath = normalizeVaultRelativePath(options.dependentPath || "");
  const dependentLines =
    options.dependentLines instanceof Set
      ? options.dependentLines
      : new Set(options.dependentLines || []);
  const out = [];
  for (const [path, snapshot] of snapshots) {
    if (!path || isDependencyStageExcludedPath(path)) {
      continue;
    }
    const route = dependencyStageRouteOf(path);
    const noteName = dependencyStageBasenameOf(path);
    for (const entry of snapshot.entries) {
      if (!entry.isTask || !entry.open) {
        continue;
      }
      if (path === dependentPath && dependentLines.has(entry.line)) {
        continue;
      }
      out.push(
        Object.freeze({
          path,
          route,
          note: noteName,
          line: entry.line,
          rawLine: entry.rawLine,
          status: entry.status,
          displayText: entry.text,
          text: entry.text,
          blockId: entry.blockId,
          existingBlockId: entry.blockId,
          idField: entry.idField,
          existingIdField: entry.idField,
          section: entry.section,
          open: true,
          blocked: entry.blocked,
          hidden: entry.hidden,
        }),
      );
    }
  }
  return Object.freeze(out);
}

function indexDependencyStageNotesFromSnapshots(snapshots) {
  const byKey = new Map();
  const byBlockId = new Map();
  const byIdField = new Map();
  const basenames = new Map();
  const register = (path, entry) => {
    const record = Object.freeze({ path, ...entry });
    if (entry.blockId) {
      const key = dependencyStageRowKey(path, entry.blockId);
      if (!byKey.has(key)) {
        byKey.set(key, record);
      }
      if (!byBlockId.has(entry.blockId)) {
        byBlockId.set(entry.blockId, []);
      }
      byBlockId.get(entry.blockId).push(record);
    }
    if (entry.idField && !byIdField.has(entry.idField)) {
      byIdField.set(entry.idField, record);
    }
    return record;
  };
  for (const [path, snapshot] of snapshots) {
    if (!path) {
      continue;
    }
    const basename = dependencyStageBasenameOf(path);
    if (!basenames.has(basename)) {
      basenames.set(basename, []);
    }
    basenames.get(basename).push(path);
    for (const entry of snapshot.entries) {
      register(path, entry);
    }
  }
  return Object.freeze({ byKey, byBlockId, byIdField, basenames });
}

// The vault-wide RESULTS pool (`docs/task-dependencies.md` §6.2): open
// tasks passing the `#task` global filter, including `ref/`, inbox,
// Blocked, and `#hide`. `notes` is `[{path, content}]`; open editor buffers
// must already override the cache in that list, so unsaved edits count.
function collectVaultDependencyCandidates(notes, options = {}) {
  return collectVaultDependencyCandidatesFromSnapshots(
    createDependencySnapshotMap(notes),
    options,
  );
}

// Lookup over everything — including closed, archived, hidden, and missing
// targets — so CURRENT rows can still be removed
// (`docs/task-dependencies.md` §6.2).
function indexDependencyStageNotes(notes) {
  return indexDependencyStageNotesFromSnapshots(createDependencySnapshotMap(notes));
}

// Resolve one Depends-On line link to its note path: same-note links stay
// put, bare basenames resolve when unique (case-insensitive), otherwise the
// full vault-relative route wins.
function resolveDependencyStageLinkTarget(linkNote, blockId, parentPath, index) {
  const id = normalizeBulletPropertyValue(blockId);
  if (!id || !index) {
    return null;
  }
  const note = String(linkNote || "");
  if (!note) {
    return normalizeVaultRelativePath(parentPath || "");
  }
  if (note.includes("/")) {
    return normalizeVaultRelativePath(`${note}.md`);
  }
  const paths = index.basenames.get(note) || [];
  const lowered = note.toLowerCase();
  const matches = paths.length > 0 ? paths : [];
  if (matches.length === 0) {
    for (const [basename, candidates] of index.basenames) {
      if (basename.toLowerCase() === lowered) {
        return normalizeVaultRelativePath(candidates[0] || "");
      }
    }
    return null;
  }
  return normalizeVaultRelativePath(matches[0] || "");
}

// CURRENT rows: the dependent's existing prerequisites resolved against
// everything, so closed, archived, hidden, and missing targets stay
// removable. Returns `{ok, rows}` or `{ok: false, reason}` for a malformed
// line (left alone, never projected).
function resolveDependencyStageCurrent(content, parentLine, parentPath, index, snapshot = null) {
  const text = String(content || "");
  const lines = snapshot && Array.isArray(snapshot.lines)
    ? snapshot.lines
    : text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(parentLine, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return Object.freeze({ ok: false, reason: "parent-out-of-range", rows: [] });
  }
  const collection = snapshot
    ? getCachedDependencyCollection(snapshot, text, at)
    : collectDependencyNavigationBullets(text, at);
  if (collection.reason) {
    return Object.freeze({ ok: false, reason: collection.reason, rows: [] });
  }
  const rows = [];
  for (const target of collection.targets) {
    const targetPath = resolveDependencyStageLinkTarget(
      target.note,
      target.blockId,
      parentPath,
      index,
    );
    const key =
      targetPath && target.blockId
        ? dependencyStageRowKey(targetPath, target.blockId)
        : null;
    const record = (key && index.byKey.get(key)) || null;
    if (!record) {
      const siblings =
        (target.blockId && index.byBlockId.get(target.blockId)) || [];
      if (siblings.length === 0) {
        rows.push(
          Object.freeze({
            kind: "current",
            path: targetPath,
            blockId: target.blockId,
            status: "?",
            displayText: `^${target.blockId} not found`,
            text: `^${target.blockId} not found`,
            missing: true,
            open: true,
            blocked: false,
            rawLine: null,
            section: null,
          }),
        );
        continue;
      }
    }
    if (record && !record.isTask) {
      rows.push(
        Object.freeze({
          kind: "current",
          path: record.path,
          blockId: record.blockId,
          status: record.status,
          displayText: record.text,
          text: record.text,
          nonTask: true,
          open: false,
          blocked: false,
          rawLine: record.rawLine,
          section: record.section,
        }),
      );
      continue;
    }
    if (record) {
      rows.push(
        Object.freeze({
          kind: "current",
          path: record.path,
          blockId: record.blockId,
          status: record.status,
          displayText: record.text,
          text: record.text,
          open: record.open,
          blocked: record.blocked,
          closed: !record.open,
          rawLine: record.rawLine,
          section: record.section,
        }),
      );
      continue;
    }
    rows.push(
      Object.freeze({
        kind: "current",
        path: targetPath,
        blockId: target.blockId,
        status: "?",
        displayText: `^${target.blockId} not found`,
        text: `^${target.blockId} not found`,
        missing: true,
        open: true,
        blocked: false,
        rawLine: null,
        section: null,
      }),
    );
  }
  return Object.freeze({ ok: true, reason: null, rows: Object.freeze(rows) });
}

// Dependency edges for cycle guards: each open task's Depends-On line links
// plus its `[dependsOn::]` field ids, resolved to `path blockId` keys.
// Unresolvable links are skipped: they never block and never guard.
function collectDependencyStageEdgesFromSnapshots(snapshots, index) {
  const edges = new Map();
  const projectPrjFromByPath = new Map();
  const add = (from, to) => {
    if (!from || !to || from === to) {
      return;
    }
    if (!edges.has(from)) {
      edges.set(from, []);
    }
    if (!edges.get(from).includes(to)) {
      edges.get(from).push(to);
    }
  };
  for (const [path, snapshot] of snapshots) {
    if (!path || !snapshot) {
      continue;
    }
    const { lines, contexts, text } = snapshot;
    for (const entry of snapshot.entries) {
      if (!entry.isTask || !entry.open) {
        continue;
      }
      const line = entry.line;
      const rawLine = String(lines[line] || "");
      const selfBlockId = entry.blockId;
      const selfIdField = entry.idField;
      const from =
        (selfBlockId && dependencyStageRowKey(path, selfBlockId)) ||
        (selfIdField && `id:${selfIdField}`) ||
        `${path}#line:${line}`;
      if (isProjectLifecycleTaskLine(rawLine)) {
        if (!projectPrjFromByPath.has(path)) {
          projectPrjFromByPath.set(path, { prjFrom: null, residentFroms: [] });
        }
        if (selfBlockId) {
          projectPrjFromByPath.get(path).prjFrom = from;
        }
      } else {
        if (!projectPrjFromByPath.has(path)) {
          projectPrjFromByPath.set(path, { prjFrom: null, residentFroms: [] });
        }
        projectPrjFromByPath.get(path).residentFroms.push({ line, from });
      }
      const collection = getCachedDependencyCollection(snapshot, text, line);
      if (!collection.reason) {
        for (const target of collection.targets) {
          const targetPath = resolveDependencyStageLinkTarget(
            target.note,
            target.blockId,
            path,
            index,
          );
          if (targetPath && target.blockId) {
            add(from, dependencyStageRowKey(targetPath, target.blockId));
          }
        }
      }
      const field = findBulletPropertyField(rawLine, "dependsOn");
      if (field && index) {
        for (const id of parseLocalTaskIdList(field.value)) {
          const record = index.byIdField.get(id);
          if (record && record.blockId) {
            add(from, dependencyStageRowKey(record.path, record.blockId));
          }
        }
      }
    }
  }
  // §13.6: residents inherit `^prj`'s outgoing edges, so cycle detection
  // sees the implicit resident → `^prj`-link edges. Only recognized
  // projects participate, matching the writer's recognition exactly.
  for (const [path, snapshot] of snapshots) {
    const tracked = projectPrjFromByPath.get(path);
    if (!tracked || !tracked.prjFrom) {
      continue;
    }
    const info = getProjectPrjDependencyResidents(snapshot.text, path);
    if (!info) {
      continue;
    }
    const inherited = edges.get(tracked.prjFrom) || [];
    if (inherited.length === 0) {
      continue;
    }
    const residentLines = new Set(info.residents.map((row) => row.line));
    for (const resident of tracked.residentFroms) {
      if (!residentLines.has(resident.line)) {
        continue;
      }
      for (const target of inherited) {
        add(resident.from, target);
      }
    }
  }
  return edges;
}

function collectDependencyStageEdges(notes, index) {
  return collectDependencyStageEdgesFromSnapshots(createDependencySnapshotMap(notes), index);
}

// Whether linking `fromKey` to `toKey` would create a cycle: `toKey` already
// reaches `fromKey` through the current graph. Returns the cycle path
// (for the tooltip) or null.
function findDependencyStageCycle(edges, fromKey, toKey) {
  if (!fromKey || !toKey || !edges) {
    return null;
  }
  if (fromKey === toKey) {
    return Object.freeze([fromKey]);
  }
  const visited = new Set([toKey]);
  const stack = [{ key: toKey, trail: [toKey] }];
  while (stack.length > 0) {
    const { key, trail } = stack.pop();
    const next = edges instanceof Map ? edges.get(key) : edges[key];
    for (const edge of next || []) {
      if (edge === fromKey) {
        return Object.freeze([...trail, fromKey]);
      }
      if (!visited.has(edge)) {
        visited.add(edge);
        stack.push({ key: edge, trail: [...trail, edge] });
      }
    }
  }
  return null;
}

// Canonical order for ties and the empty query
// (`docs/task-dependencies.md` §6.3): same-note tasks in document order,
// then In Progress, Next, Ready (by path, then line), then `#hide`.
// Relations pass `{ blockedWithReady: true }` so Blocked shares Ready's lane,
// plus `{ dailyNewestFirst: true }` so admitted daily Event Tasks rank after
// non-daily rows with newest day first (LG28). Daily rows are never compared
// by path, keeping a strict total order.
function compareDependencyStageCanonical(first, second, dependentPath, options = {}) {
  const firstSame = first.path === dependentPath;
  const secondSame = second.path === dependentPath;
  if (firstSame !== secondSame) {
    return firstSame ? -1 : 1;
  }
  if (firstSame && secondSame) {
    return first.line - second.line;
  }
  // `#hide` ranks last, ahead of the lane: a hidden In Progress task sorts
  // after a visible Ready one (`docs/task-dependencies.md` §6.3).
  if (Boolean(first.hidden) !== Boolean(second.hidden)) {
    return first.hidden ? 1 : -1;
  }
  const blockedWithReady = Boolean(options && options.blockedWithReady);
  const lane = (status) => {
    if (status === "/") return 0;
    if (status === "*") return 1;
    if (status === " ") return 2;
    if (blockedWithReady && status === "?") return 2;
    return 3;
  };
  const laneDiff = lane(first.status) - lane(second.status);
  if (laneDiff !== 0) {
    return laneDiff;
  }
  if (Boolean(options && options.dailyNewestFirst)) {
    const firstDaily = Boolean(first && first.dailyNote === true);
    const secondDaily = Boolean(second && second.dailyNote === true);
    if (firstDaily !== secondDaily) {
      return firstDaily ? 1 : -1;
    }
    if (firstDaily && secondDaily) {
      const firstDay = String((first && first.noteDay) || "");
      const secondDay = String((second && second.noteDay) || "");
      if (firstDay !== secondDay) {
        return firstDay < secondDay ? 1 : -1;
      }
      return (first.line || 0) - (second.line || 0);
    }
  }
  if (first.path !== second.path) {
    return first.path < second.path ? -1 : 1;
  }
  return first.line - second.line;
}

// The staged view: CURRENT, then one RESULTS list ranked by score, with a
// BLOCKED header only on an empty filter (`docs/task-dependencies.md` §6).
// Guards disable rows with a reason: the
// dependent itself, a cycle (checked on the graph after the whole batch,
// with the path), an unencodable target, or a stale target/dependent
// (refused at commit time, then reopened fresh). Removing a link is always
// allowed, so CURRENT rows are never disabled. At most about 60 rows
// render; typing reaches the rest.
// ---- src/300-dependency-stage.js ----
function planDependencyStageView(args = {}) {
  const current = Array.isArray(args.current) ? args.current : [];
  const pool = Array.isArray(args.candidates) ? args.candidates : [];
  const query = String(args.query || "");
  const dependent = args.dependent || {};
  const dependentPath = normalizeVaultRelativePath(dependent.path || "");
  const dependentLine = Math.floor(numericOrDefault(dependent.line, -1));
  const dependentKey = dependent.key || null;
  const edges = args.edges || new Map();
  const linkedKeys = args.linkedKeys instanceof Set ? args.linkedKeys : new Set();
  // Counted sessions (`N<Ctrl+Shift+P>`) match each candidate against every
  // source task's field set, so partially linked rows stay visible with a
  // `k/n depend` badge instead of being folded into CURRENT.
  const sourceValueSets =
    Array.isArray(args.sourceValueSets) && args.sourceValueSets.length > 0
      ? args.sourceValueSets.map((values) =>
          values instanceof Set ? values : new Set(values || []),
        )
      : null;
  const maxRows = Math.max(
    1,
    Math.floor(numericOrDefault(args.maxRows, DEPENDENCY_STAGE_MAX_ROWS)),
  );
  const markedCurrent = current.map((row, index) =>
    Object.freeze({
      ...row,
      stageSection: "current",
      alreadyLinked: true,
      firstInSection: index === 0,
      headerSection: index === 0 ? "current" : null,
      markKey:
        row.markKey ||
        (row.path
          ? `${normalizeVaultRelativePath(row.path)}#${row.blockId || `line:${row.line}`}`
          : row.line),
    }),
  );
  const candidateAliases = (candidate) => {
    const depValue =
      candidate.idField ||
      (candidate.blockId
        ? tryDependencyId(candidate.path, candidate.blockId)
        : null) ||
      "";
    return [depValue, candidate.idField, candidate.blockId]
      .map(normalizeBulletPropertyValue)
      .filter(Boolean);
  };
  const seen = new Set(linkedKeys);
  const fresh = [];
  for (const candidate of pool) {
    const key =
      candidate.path && candidate.blockId
        ? dependencyStageRowKey(candidate.path, candidate.blockId)
        : null;
    if (
      candidate.path === dependentPath &&
      candidate.line === dependentLine
    ) {
      continue;
    }
    if (sourceValueSets) {
      const aliases = candidateAliases(candidate);
      const linkedCount = sourceValueSets.filter((values) =>
        aliases.some((alias) => values.has(alias)),
      ).length;
      // Fully linked rows live in CURRENT; mixed and unlinked stay in RESULTS.
      if (linkedCount > 0 && linkedCount === sourceValueSets.length) {
        continue;
      }
      fresh.push({ candidate, key, linkedCount });
      continue;
    }
    if (key && seen.has(key)) {
      continue;
    }
    if (key) {
      seen.add(key);
    }
    fresh.push({ candidate, key, linkedCount: 0 });
  }
  // Empty query shows only what the design lists: CURRENT is separate,
  // then same-note tasks plus the In Progress and Next lanes. Ready tasks
  // from other notes (and Blocked elsewhere) need typing.
  const emptyQuery = !query.trim();
  const searchable = emptyQuery
    ? fresh.filter(
        (entry) =>
          entry.candidate.path === dependentPath ||
          entry.candidate.status === "/" ||
          entry.candidate.status === "*",
      )
    : fresh;
  // One RESULTS list ranked by score (§6.3): status only breaks exact-score
  // ties (open before Blocked, then canonical order), and the cap counts
  // this merged order so a strong Blocked match is never folded away.
  const ordered = orderDependencyStageMatches(
    searchable.map((entry) => entry.candidate),
    query,
    (left, right) =>
      Number(Boolean(left.blocked)) - Number(Boolean(right.blocked)) ||
      compareDependencyStageCanonical(left, right, dependentPath),
  );
  const room = Math.max(0, maxRows - markedCurrent.length);
  const picked = ordered.slice(0, room);
  const statusClasses = picked.map((candidate) =>
    candidate.blocked ? "blocked" : "results",
  );
  const headers = dependencyStageHeaderSections(statusClasses, emptyQuery);
  const linkedByCandidate = new Map(
    fresh.map((entry) => [entry.candidate, entry.linkedCount || 0]),
  );
  // Task descriptions by stage row key, so disabled cycle rows tooltip
  // readable `description → description` paths instead of raw
  // `path blockId` keys (`docs/task-dependencies.md` §6.4). Keys without a
  // row (the dependent itself, `id:` values) keep the raw key.
  const labelByKey = new Map();
  for (const row of [...current, ...pool]) {
    if (!row) {
      continue;
    }
    const rowKey =
      row.path && row.blockId
        ? dependencyStageRowKey(row.path, row.blockId)
        : null;
    const label = row.displayText || row.text || null;
    if (rowKey && label && !labelByKey.has(rowKey)) {
      labelByKey.set(rowKey, label);
    }
  }
  const labelDependencyStageCycle = (cycle) =>
    Object.freeze(
      (Array.isArray(cycle) ? cycle : []).map((key) =>
        labelByKey.has(key) ? labelByKey.get(key) : key,
      ),
    );
  // The dependent line itself is never a pool row, so its description would
  // otherwise fall back to the raw key at the end of every cycle path.
  if (
    dependentKey &&
    !labelByKey.has(dependentKey) &&
    (dependent.displayText || dependent.text)
  ) {
    labelByKey.set(dependentKey, dependent.displayText || dependent.text);
  }
  const isProjectPrjDependent = dependent && dependent.isProjectPrj === true;
  const descendantPaths = new Set(
    (Array.isArray(dependent.projectDescendantPaths)
      ? dependent.projectDescendantPaths
      : []
    ).map((path) => normalizeVaultRelativePath(path)),
  );
  const guard = (candidate) => {
    const key =
      candidate.path && candidate.blockId
        ? dependencyStageRowKey(candidate.path, candidate.blockId)
        : null;
    // §13.6: a `^prj` link to its own note is a guaranteed deadlock, so
    // every same-note row is disabled. Removing an existing link stays
    // allowed: CURRENT rows never pass through this guard.
    if (isProjectPrjDependent && candidate.path === dependentPath) {
      return {
        disabled: true,
        reason: "inside this project",
        cycle: null,
        cycleLabels: null,
      };
    }
    if (
      isProjectPrjDependent &&
      candidate.path &&
      descendantPaths.has(normalizeVaultRelativePath(candidate.path))
    ) {
      return {
        disabled: true,
        reason: "inside a sub-project of this project",
        cycle: null,
        cycleLabels: null,
      };
    }
    if (key && dependentKey) {
      if (key === dependentKey) {
        const selfCycle = Object.freeze([dependentKey]);
        return {
          disabled: true,
          reason: "this task",
          cycle: selfCycle,
          cycleLabels: labelDependencyStageCycle(selfCycle),
        };
      }
      let cycle = findDependencyStageCycle(edges, dependentKey, key);
      // A `^prj` add implicitly adds resident `→ X` for every open
      // resident (§13.10), so X depending on a resident is refused too.
      if (!cycle && isProjectPrjDependent && key) {
        const residentKeys = Array.isArray(dependent.projectResidentKeys)
          ? dependent.projectResidentKeys
          : [];
        for (const residentKey of residentKeys) {
          if (!residentKey || residentKey === dependentKey) {
            continue;
          }
          cycle = findDependencyStageCycle(edges, residentKey, key);
          if (cycle) {
            break;
          }
        }
      }
      if (cycle) {
        return {
          disabled: true,
          reason: "would create a cycle",
          cycle: Object.freeze(cycle),
          cycleLabels: labelDependencyStageCycle(cycle),
        };
      }
    }
    if (
      candidate.blockId &&
      !candidate.idField &&
      !tryDependencyId(candidate.path, candidate.blockId)
    ) {
      return {
        disabled: true,
        reason: "path can't be an id",
        cycle: null,
        cycleLabels: null,
      };
    }
    return { disabled: false, reason: null, cycle: null, cycleLabels: null };
  };
  const shape = (candidate, section, header) => {
    const verdict = guard(candidate);
    const depValue =
      candidate.idField ||
      (candidate.blockId
        ? tryDependencyId(candidate.path, candidate.blockId)
        : null) ||
      "";
    // BLOCKED rows name what blocks them (`docs/task-dependencies.md` §6.3):
    // `🔒 waits on N` only when N >= 1 open prerequisites remain (the
    // candidate's own open count when the builder attached one, else the
    // post-batch graph edges, else 0 — never `waits on 0`); with no open
    // prerequisite, a future `scheduled` date reads `🔒 scheduled
    // YYYY-MM-DD`, and otherwise the row reads `🔒 blocked`.
    let waitsOn = null;
    let blockedBadge = null;
    if (section === "blocked") {
      const rowKey =
        candidate.path && candidate.blockId
          ? dependencyStageRowKey(candidate.path, candidate.blockId)
          : null;
      const edgeCount =
        rowKey && edges instanceof Map && edges.get(rowKey)
          ? edges.get(rowKey).length
          : null;
      const open =
        Number.isInteger(candidate.openCount) && candidate.openCount >= 0
          ? candidate.openCount
          : Number.isInteger(edgeCount) && edgeCount > 0
            ? edgeCount
            : 0;
      if (open >= 1) {
        waitsOn = open;
        blockedBadge = `🔒 waits on ${open}`;
      } else {
        const scheduled =
          typeof candidate.scheduledDate === "string" &&
          /^\d{4}-\d{2}-\d{2}$/.test(candidate.scheduledDate)
            ? candidate.scheduledDate
            : null;
        blockedBadge = scheduled ? `🔒 scheduled ${scheduled}` : "🔒 blocked";
      }
    }
    return Object.freeze({
      kind: "local-task",
      stageSection: section,
      firstInSection: header !== null,
      headerSection: header,
      path: candidate.path,
      blockId: candidate.blockId,
      route: candidate.route,
      note: candidate.note,
      noteLabel:
        candidate.path && candidate.path !== dependentPath
          ? dependencyStageBasenameOf(candidate.path)
          : null,
      line: candidate.line,
      rawLine: candidate.rawLine,
      status: candidate.status,
      displayText: candidate.displayText,
      text: candidate.text,
      searchText: [
        candidate.displayText,
        candidate.route,
        candidate.blockId
          ? `${candidate.route}:${candidate.blockId}`
          : "",
        candidate.blockId || "",
        candidate.section || "",
        candidate.note || "",
      ]
        .filter(Boolean)
        .join(" "),
      value: depValue,
      dependencyValue: depValue,
      legacyDependencyValue: candidate.idField || candidate.blockId || "",
      linkBlockId: candidate.blockId || "",
      badgeId: candidate.blockId || "",
      existingBlockId: candidate.blockId,
      existingIdField: candidate.idField,
      alreadyLinked: sourceValueSets
        ? (linkedByCandidate.get(candidate) || 0) === sourceValueSets.length &&
          sourceValueSets.length > 0
        : false,
      linkedSourceCount: linkedByCandidate.get(candidate) || 0,
      sourceCount: sourceValueSets ? sourceValueSets.length : 1,
      linkState: !sourceValueSets
        ? "none"
        : (linkedByCandidate.get(candidate) || 0) === 0
          ? "none"
          : (linkedByCandidate.get(candidate) || 0) >= sourceValueSets.length
            ? "all"
            : "mixed",
      needsBlockIdPrompt: !candidate.blockId,
      needsDependencyValue: !depValue,
      needsPromptForAdd: !candidate.blockId,
      hidden: candidate.hidden,
      section: candidate.section,
      markKey: `${candidate.path}#${candidate.line >= 0 ? candidate.line : (candidate.blockId || candidate.displayText)}`,
      disabled: verdict.disabled,
      disabledReason: verdict.reason,
      cycle: verdict.cycle,
      cycleLabels: verdict.cycleLabels || null,
      waitsOn,
      blockedBadge,
    });
  };
  const out = [...markedCurrent];
  picked.forEach((candidate, index) =>
    out.push(shape(candidate, statusClasses[index], headers[index])),
  );
  // The ~60-row cap truncates: append the "type to search N more" hint row
  // so keyboard filtering reaches the rest (`docs/task-dependencies.md` §6.3).
  const hiddenCount = Math.max(0, ordered.length - picked.length);
  if (hiddenCount > 0) {
    out.push(
      Object.freeze({
        kind: "stage-more",
        stageSection: statusClasses[statusClasses.length - 1] || "results",
        firstInSection: false,
        headerSection: null,
        path: null,
        blockId: null,
        displayText: `type to search ${hiddenCount} more`,
        text: `type to search ${hiddenCount} more`,
        searchText: "",
        hiddenCount,
        disabled: true,
        disabledReason: `type to search ${hiddenCount} more`,
        cycle: null,
        cycleLabels: null,
        waitsOn: null,
      }),
    );
  }
  return Object.freeze(out);
}

// Normalize one Tasks cache task to pool shape, or null when it carries no
// usable location. Field names differ across Tasks versions, so every known
// alias is tried; the vault scan covers whatever falls through.
function normalizeStageCacheTask(entry) {
  const task = entry && typeof entry === "object" ? entry : null;
  if (!task) {
    return null;
  }
  const location =
    task.taskLocation && typeof task.taskLocation === "object"
      ? task.taskLocation
      : {};
  const file = task.file && typeof task.file === "object" ? task.file : {};
  const path = normalizeVaultRelativePath(
    task.path || location.path || file.path || "",
  );
  if (!path) {
    return null;
  }
  const status =
    (task.status && task.status.symbol) ||
    task.statusSymbol ||
    (typeof task.status === "string" ? task.status : null) ||
    " ";
  const lineCandidates = [
    task.lineNumber,
    task.line,
    location.lineNumber,
    location.line,
  ];
  let line = -1;
  for (const candidate of lineCandidates) {
    const numeric = Math.floor(numericOrDefault(candidate, Number.NaN));
    if (Number.isFinite(numeric) && numeric >= 0) {
      line = numeric;
      break;
    }
  }
  const rawLine =
    typeof task.originalMarkdown === "string" ? task.originalMarkdown : null;
  const text =
    (typeof task.description === "string" && task.description) ||
    (typeof task.text === "string" && task.text) ||
    (rawLine ? cleanTaskDisplayText(rawLine) : "(untitled task)");
  const trailingId =
    (typeof task.blockId === "string" && task.blockId) ||
    (rawLine ? getTrailingBlockId(rawLine) : null) ||
    null;
  const idField =
    (typeof task.id === "string" && task.id) ||
    (task.taskId && String(task.taskId)) ||
    null;
  const dependsOn = Array.isArray(task.dependsOn)
    ? task.dependsOn
        .map(normalizeBulletPropertyValue)
        .filter(Boolean)
    : [];
  return Object.freeze({
    path,
    route: dependencyStageRouteOf(path),
    note: dependencyStageBasenameOf(path),
    line,
    rawLine,
    status,
    displayText: text,
    text,
    blockId: trailingId ? normalizeBulletPropertyValue(trailingId) : null,
    existingBlockId: trailingId ? normalizeBulletPropertyValue(trailingId) : null,
    idField: idField ? normalizeBulletPropertyValue(idField) : null,
    existingIdField: idField ? normalizeBulletPropertyValue(idField) : null,
    section:
      (typeof task.section === "string" && task.section) ||
      (typeof task.precedingHeader === "string" && task.precedingHeader) ||
      null,
    open: OPEN_OBSIDIAN_TASK_STATUSES.has(status),
    blocked: status === "?",
    hidden: Boolean(task.hidden),
    dependsOn: Object.freeze(dependsOn),
  });
}

// Merge Tasks cache records under open-buffer notes: buffers win per note
// (unsaved edits count), cache-only notes fill the rest. Exclusions and the
// dependent match the note parser exactly.
function mergeStageCacheCandidates(cacheTasks, notes, options = {}) {
  const dependentPath = normalizeVaultRelativePath(options.dependentPath || "");
  const dependentLines =
    options.dependentLines instanceof Set
      ? options.dependentLines
      : new Set(options.dependentLines || []);
  const buffered = new Set(
    (Array.isArray(notes) ? notes : []).map((note) =>
      normalizeVaultRelativePath(note.path || ""),
    ),
  );
  const out = collectVaultDependencyCandidates(notes, {
    dependentPath,
    dependentLines,
  }).slice();
  for (const record of cacheTasks || []) {
    if (!record || buffered.has(record.path)) {
      continue;
    }
    if (isDependencyStageExcludedPath(record.path)) {
      continue;
    }
    if (!record.open) {
      continue;
    }
    if (
      record.path === dependentPath &&
      dependentLines.has(record.line)
    ) {
      continue;
    }
    out.push(record);
  }
  return Object.freeze(out);
}

// Register cache-only records in the lookup (for CURRENT rows and pill
// counts) and the basename table (for link resolution).
function registerStageCacheRecords(index, cacheTasks) {
  if (!index) {
    return;
  }
  for (const record of cacheTasks || []) {
    if (!record) {
      continue;
    }
    const basename = dependencyStageBasenameOf(record.path);
    if (index.basenames && !index.basenames.has(basename)) {
      index.basenames.set(basename, []);
    }
    if (index.basenames && !index.basenames.get(basename).includes(record.path)) {
      index.basenames.get(basename).push(record.path);
    }
    if (record.blockId) {
      const key = dependencyStageRowKey(record.path, record.blockId);
      if (key && index.byKey && !index.byKey.has(key)) {
        index.byKey.set(key, record);
      }
      if (index.byBlockId) {
        if (!index.byBlockId.has(record.blockId)) {
          index.byBlockId.set(record.blockId, []);
        }
        index.byBlockId.get(record.blockId).push(record);
      }
    }
    if (record.idField && index.byIdField && !index.byIdField.has(record.idField)) {
      index.byIdField.set(record.idField, record);
    }
  }
}

// Cycle-guard edges from cache `[dependsOn::]` fields for notes with no
// open buffer: identity through the block id when present, else the stable
// `id:` key shared with the note parser's edge scheme.
function mergeStageCacheEdges(edges, cacheTasks, index) {
  if (!(edges instanceof Map)) {
    return;
  }
  for (const record of cacheTasks || []) {
    if (!record || !Array.isArray(record.dependsOn) || record.dependsOn.length === 0) {
      continue;
    }
    const from =
      (record.blockId && dependencyStageRowKey(record.path, record.blockId)) ||
      (record.idField ? `id:${record.idField}` : null);
    if (!from) {
      continue;
    }
    for (const id of record.dependsOn) {
      const target = index && index.byIdField ? index.byIdField.get(id) : null;
      const to =
        target && target.blockId
          ? dependencyStageRowKey(target.path, target.blockId)
          : null;
      if (to && to !== from) {
        if (!edges.has(from)) {
          edges.set(from, []);
        }
        if (!edges.get(from).includes(to)) {
          edges.get(from).push(to);
        }
      }
    }
  }
}

// Locate one open task by its cleaned display text: cache-only `+ id` rows
// carry no staged line text, so the target is matched fresh. Exactly one
// block-id-less match links; anything else refuses as stale.
function locateStageDisplayText(content, displayText) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const contexts = getMarkdownLineContextsForLines(lines);
  const want = String(displayText || "");
  const matches = [];
  for (let line = 0; line < lines.length; line += 1) {
    if (!isObsidianTaskAtLine(text, line, contexts, lines)) {
      continue;
    }
    if (!isOpenObsidianTaskLine(lines[line])) {
      continue;
    }
    if (cleanTaskDisplayText(lines[line]) !== want) {
      continue;
    }
    matches.push(
      Object.freeze({
        line,
        rawLine: String(lines[line] || ""),
        blockId: getTrailingBlockId(lines[line]),
      }),
    );
    if (matches.length > 1) {
      return null;
    }
  }
  // The unique match, with or without a block id (the caller routes `+ id`
  // prompts versus ready adds); ambiguous or absent matches refuse.
  return matches.length === 1 ? matches[0] : null;
}

// True when a non-collapsed selection covers two or more `#task` lines: the
// stage edits one dependent, so such selections are refused with a reason.
function editorSelectionSpansTasks(cm, content) {
  try {
    if (!cm || typeof cm.listSelections !== "function") {
      return false;
    }
    const text = String(content || "");
    const lines = text.split(/\r?\n/);
    const contexts = getMarkdownLineContextsForLines(lines);
    for (const selection of cm.listSelections() || []) {
      const anchor = selection && selection.anchor;
      const head = selection && selection.head;
      if (!anchor || !head) {
        continue;
      }
      if (anchor.line === head.line && anchor.ch === head.ch) {
        continue;
      }
      const from = Math.max(0, Math.min(anchor.line, head.line));
      const to = Math.max(0, Math.max(anchor.line, head.line));
      let tasks = 0;
      for (let line = from; line <= to && tasks < 2; line += 1) {
        if (isObsidianTaskAtLine(text, line, contexts, lines)) {
          tasks += 1;
        }
      }
      if (tasks >= 2) {
        return true;
      }
    }
    return false;
  } catch (_error) {
    return false;
  }
}

// Entry-point resolution (`docs/task-dependencies.md` §§6.1, 15.2):
// managed dependency lines resolve to their owning task, never the link under
// the cursor. The direction-specific caller decides whether to skip the card.
function resolveDependencyStageEntry(content, line) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(line, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return Object.freeze({ ok: false, parentLine: null, reason: "no-task" });
  }
  const owning = findOwningTaskLine(lines, at);
  if (owning === null) {
    return Object.freeze({ ok: false, parentLine: null, reason: "no-task" });
  }
  if (
    findDependencyLineIndex(lines, owning) === at &&
    parseDependencyLine(String(lines[at] || ""), { isDirectChildOfTask: true })
      .verdict === "accept"
  ) {
    return Object.freeze({
      ok: true,
      parentLine: owning,
      lineKind: "depends-on",
      skipPropertyStep: true,
      reason: null,
    });
  }
  // Rule 8 (BK20): a BLOCKS line acts on its owner, never on the chip under
  // the cursor. Ctrl+Shift+P opens that owner's reverse stage directly.
  if (
    parseBlocksLine(String(lines[at] || ""), { isDirectChildOfTask: true })
      .verdict !== "not-a-line"
  ) {
    return Object.freeze({
      ok: true,
      parentLine: owning,
      lineKind: "blocks",
      skipPropertyStep: false,
      reason: null,
    });
  }
  // Task relations Rule 8 (LG8): either relation line acts on its owner,
  // never on the chip under the cursor. The direction-specific caller opens
  // the matching stage.
  if (
    parseLinksLine(String(lines[at] || ""), { isDirectChildOfTask: true })
      .verdict !== "not-a-line"
  ) {
    return Object.freeze({
      ok: true,
      parentLine: owning,
      lineKind: "links",
      skipPropertyStep: false,
      reason: null,
    });
  }
  if (
    parseLinkedFromLine(String(lines[at] || ""), { isDirectChildOfTask: true })
      .verdict !== "not-a-line"
  ) {
    return Object.freeze({
      ok: true,
      parentLine: owning,
      lineKind: "linked-from",
      skipPropertyStep: false,
      reason: null,
    });
  }
  return Object.freeze({
    ok: true,
    parentLine: owning,
    lineKind: null,
    skipPropertyStep: false,
    reason: null,
  });
}

function taskStatusLabel(status) {
  return `[${status || " "}]`;
}

function taskStatusClass(status) {
  if (status === "/") {
    return "active";
  }

  if (status === "*") {
    return "next";
  }

  return "todo";
}

function validateBlockIdCandidate(id, content, options = {}) {
  const reservedIds =
    options.reservedIds instanceof Set
      ? options.reservedIds
      : new Set(options.reservedIds || []);
  const value = normalizeBulletPropertyValue(id);
  if (!value) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "invalid",
      message: "Enter a block ID",
    });
  }

  if (!BULLET_PROPERTY_BLOCK_ID_RE.test(value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "invalid",
      message: "Use only letters, numbers, and hyphens",
    });
  }

  if (blockIdExistsInContent(content, value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "duplicate",
      message: "Already exists in this file",
    });
  }

  if (reservedIds.has(value)) {
    return Object.freeze({
      id: value,
      valid: false,
      state: "duplicate",
      message: "Already chosen in this batch",
    });
  }

  return Object.freeze({
    id: value,
    valid: true,
    state: "valid",
    message: "Ready to create",
  });
}

function createBulletPropertyValueItems(propertyItem, baseDate) {
  const property = propertyItem.property;
  const currentValue = propertyItem.currentValue || "";
  if (property.values === "date") {
    return createBulletPropertyDateItems(baseDate, currentValue, {
      includeToday: normalizeBulletPropertyName(property.name) !== "scheduled",
    });
  }

  if (property.values === "local_task_id") {
    return [];
  }

  if (property.values === "priority") {
    return property.levels.map((level) => ({
      kind: "value",
      value: level.value,
      label: level.label,
      detail: `${level.value} · in ${level.minDays}–${level.maxDays} days`,
      current: level.value === currentValue,
      dynamic: false,
      priorityLevel: level,
      searchText: `${level.label} ${level.value} ${level.minDays}–${level.maxDays} days`,
    }));
  }

  return property.values.map((value) => ({
    kind: "value",
    value,
    label: value,
    detail: value === currentValue ? "Current value" : "",
    current: value === currentValue,
    dynamic: false,
    searchText: value,
  }));
}

function taskCardSessionContext(context = {}) {
  const content = String(context.content || "");
  const cursorLine = Math.floor(
    numericOrDefault(
      context.cursorLine ?? (context.cursor && context.cursor.line),
      0,
    ),
  );
  const lines = content.split(/\r?\n/);
  const lineText = String(
    context.lineText ?? lines[cursorLine] ?? "",
  );
  const linkSession = context.linkSession || null;
  const taskSession = context.taskSession || null;
  if (
    linkSession &&
    linkSession.kind === "task-link" &&
    Array.isArray(linkSession.resolved)
  ) {
    const resolvedTargets = deduplicateTaskCardTargets(linkSession.resolved).map(
      (entry) => entry.target,
    );
    return Object.freeze({
      type: "linked",
      content,
      lineText,
      cursorLine,
      taskSession,
      linkSession,
      targets: resolvedTargets,
      sourceTargets: linkSession.targets || [],
      targetCount: resolvedTargets.length,
      requestedCount: linkSession.requestedCount || linkSession.resolved.length,
      clamped: linkSession.clamped === true,
      valid: linkSession.valid !== false && resolvedTargets.length > 0,
      error:
        linkSession.valid === false
          ? linkSession.error || "Linked task context is unavailable"
          : resolvedTargets.length > 0
            ? null
            : "No linked tasks are available",
    });
  }
  if (
    taskSession &&
    taskSession.explicit &&
    Array.isArray(taskSession.targets) &&
    taskSession.targets.length > 0
  ) {
    const validation = validateCountedTaskSession(content, taskSession);
    return Object.freeze({
      type: "counted",
      content,
      lineText,
      cursorLine,
      taskSession,
      linkSession: null,
      targets: taskSession.targets,
      sourceTargets: taskSession.targets,
      targetCount: taskSession.targets.length,
      requestedCount: taskSession.requestedCount || taskSession.targets.length,
      clamped: taskSession.clamped === true,
      valid: validation.valid,
      error: validation.valid ? null : validation.error,
    });
  }
  const target = Object.freeze({
    line: cursorLine,
    rawLine: lineText,
    path: context.filePath || "",
  });
  return Object.freeze({
    type: "single",
    content: content || lineText,
    lineText,
    cursorLine,
    taskSession: null,
    linkSession: null,
    targets: lineText ? [target] : [],
    sourceTargets: lineText ? [target] : [],
    targetCount: lineText ? 1 : 0,
    requestedCount: lineText ? 1 : 0,
    clamped: false,
    valid: Boolean(lineText),
    error: lineText ? null : "No task or bullet is selected",
  });
}

function taskCardTargetIdentity(target, index = 0) {
  const item = target && typeof target === "object" ? target : {};
  const path = normalizeVaultRelativePath(
    item.path || item.filePath || (item.file && item.file.path) || "",
  );
  const rawLine = String(item.rawLine || "");
  const blockId = normalizeBulletPropertyValue(
    item.blockId || item.id || getTrailingBlockId(rawLine),
  );
  if (blockId) {
    return `${path}#^${blockId}`;
  }
  if (Number.isInteger(item.line)) {
    return `${path}:line:${item.line}`;
  }
  return `${path}:target:${index}:${rawLine}`;
}

function deduplicateTaskCardTargets(targets) {
  const items = Array.isArray(targets) ? targets : [];
  const seen = new Set();
  const unique = [];
  for (let index = 0; index < items.length; index += 1) {
    const target = items[index];
    const id = taskCardTargetIdentity(target, index);
    if (seen.has(id)) {
      continue;
    }
    seen.add(id);
    unique.push(Object.freeze({ id, target }));
  }
  return Object.freeze(unique);
}

// ---- src/302-blocks-stage-view.js ----
// Reverse Blocks… stage view (`docs/task-dependencies.md` §15.3–§15.5).
// Pool, edges, and index come from the forward vault stage; this file
// inverts CURRENT, swaps the guards, ranks today-first, and builds the
// consequence strip. Nothing here reads a BLOCKS line.

function blocksStageSourceAliases(source) {
  const aliases = [];
  const idField = normalizeBulletPropertyValue(source && source.idField);
  const blockId = normalizeBulletPropertyValue(source && source.blockId);
  const path = normalizeVaultRelativePath((source && source.path) || "");
  if (idField) {
    aliases.push(idField);
  }
  if (blockId) {
    aliases.push(blockId);
    const encoded = tryDependencyId(path, blockId);
    if (encoded) {
      aliases.push(normalizeBulletPropertyValue(encoded));
    }
  }
  return [...new Set(aliases.filter(Boolean))];
}

function blocksStageSourceFromLine(content, path, line) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(line, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return null;
  }
  const rawLine = String(lines[at] || "");
  const blockId = getTrailingBlockId(rawLine);
  const idFieldRaw = findBulletPropertyField(rawLine, "id");
  const idField = idFieldRaw
    ? normalizeBulletPropertyValue(idFieldRaw.value)
    : null;
  const displayText = cleanTaskDisplayText(rawLine);
  const key =
    (blockId && dependencyStageRowKey(path, blockId)) ||
    (idField ? `id:${idField}` : `${normalizeVaultRelativePath(path)}#line:${at}`);
  const source = {
    path: normalizeVaultRelativePath(path),
    line: at,
    rawLine,
    text: rawLine,
    blockId: blockId ? normalizeBulletPropertyValue(blockId) : null,
    idField,
    displayText,
    textDisplay: displayText,
    key,
    status: getObsidianTaskCheckboxStatus(rawLine),
    needsBlockId: !blockId,
    isProjectPrj: Boolean(isProjectPrjDependencyParent(text, path, at)),
    projectResidentKeys: projectDependentResidentKeys(text, path, at),
    projectDescendantPaths: Object.freeze([]),
  };
  source.aliases = Object.freeze(blocksStageSourceAliases(source));
  return Object.freeze(source);
}

function collectBlocksStageSources(stage) {
  const path = normalizeVaultRelativePath(
    (stage && stage.dependent && stage.dependent.path) || "",
  );
  const content =
    (stage && stage.files instanceof Map && stage.files.get(path)) || "";
  const lines = Array.isArray(stage && stage.parentLines)
    ? stage.parentLines
    : [];
  const sources = [];
  for (const line of lines) {
    const source = blocksStageSourceFromLine(content, path, line);
    if (source) {
      sources.push(source);
    }
  }
  return Object.freeze(sources);
}

function taskDependsOnLineIsMalformed(content, parentLine) {
  const text = String(content || "");
  const lines = text.split(/\r?\n/);
  const at = Math.floor(numericOrDefault(parentLine, Number.NaN));
  if (!Number.isFinite(at) || at < 0 || at >= lines.length) {
    return false;
  }
  const verdicts = dependencyHandEditChildVerdicts(lines, at);
  if (verdicts.some((entry) => entry.verdict === "malformed")) {
    return true;
  }
  return verdicts.filter((entry) => entry.verdict === "accept").length > 1;
}

function collectBlocksStageTodayLinks(dailyContent, dailyPath, index) {
  const text = String(dailyContent || "");
  if (!text) {
    return Object.freeze([]);
  }
  const { entries } = collectPomodoroEntries(text);
  const { lines } = splitMarkdownContent(text);
  const open = (Array.isArray(entries) ? entries : []).filter(
    (entry) => entry && entry.open,
  );
  const timedOpen = open.filter(
    (entry) =>
      entry.placeholder !== true &&
      typeof entry.rangeText === "string" &&
      entry.rangeText &&
      entry.rangeText !== "()",
  );
  const runningEntry = timedOpen.length === 1 ? timedOpen[0] : null;
  const ordered = open.slice().sort((left, right) => {
    const leftRun = left === runningEntry ? 0 : 1;
    const rightRun = right === runningEntry ? 0 : 1;
    if (leftRun !== rightRun) {
      return leftRun - rightRun;
    }
    return left.entryLine - right.entryLine;
  });
  const out = [];
  let order = 0;
  for (const entry of ordered) {
    const running = entry === runningEntry;
    const label = String(entry.name || "").trim() || "POMODORO";
    const range = String(entry.rangeText || "").replace(/^\(|\)$/g, "");
    for (
      let line = entry.childStartLine;
      line < entry.childEndLineExclusive;
      line += 1
    ) {
      const lineText = String(lines[line] || "");
      const occurrences = collectPomodoroBlockLinkOccurrences(lineText);
      if (!isDedicatedPomodoroLinkLine(lineText, occurrences)) {
        continue;
      }
      const childBlock = findCurrentBulletChildBlock(lines, line);
      let childNotes = 0;
      if (childBlock && childBlock.endLineExclusive > childBlock.startLine) {
        for (
          let child = childBlock.startLine;
          child < childBlock.endLineExclusive;
          child += 1
        ) {
          if (PROJECT_LIST_ITEM_RE.test(String(lines[child] || ""))) {
            childNotes += 1;
          }
        }
      }
      for (const occurrence of occurrences) {
        if (!occurrence || occurrence.struck) {
          continue;
        }
        const targetPath = resolveDependencyStageLinkTarget(
          occurrence.target,
          occurrence.blockId,
          dailyPath,
          index,
        );
        const key =
          targetPath && occurrence.blockId
            ? dependencyStageRowKey(targetPath, occurrence.blockId)
            : null;
        if (!key) {
          continue;
        }
        out.push(
          Object.freeze({
            key,
            path: targetPath,
            blockId: occurrence.blockId,
            label,
            range,
            running,
            childNotes,
            order: order,
          }),
        );
        order += 1;
      }
    }
  }
  return Object.freeze(out);
}

function blocksStageTodayMap(todayLinks) {
  const map = new Map();
  for (const link of Array.isArray(todayLinks) ? todayLinks : []) {
    if (!link || !link.key || map.has(link.key)) {
      continue;
    }
    map.set(link.key, link);
  }
  return map;
}

function collectBlocksStageCurrent(stage, sources) {
  const sourceList = Array.isArray(sources) ? sources : [];
  const sourceKeys = new Set(sourceList.map((source) => source.key).filter(Boolean));
  const sourceIds = new Set(
    sourceList.flatMap((source) =>
      Array.isArray(source.aliases) ? source.aliases : [],
    ),
  );
  const edges = (stage && stage.edges instanceof Map) ? stage.edges : new Map();
  const index = stage && stage.index;
  const byKey = index && index.byKey instanceof Map ? index.byKey : new Map();
  const candidates = Array.isArray(stage && stage.candidates)
    ? stage.candidates
    : [];
  const rows = [];
  const seen = new Set();
  const pushRecord = (record, extra = {}) => {
    if (!record) {
      return;
    }
    const key =
      record.path && record.blockId
        ? dependencyStageRowKey(record.path, record.blockId)
        : extra.key || null;
    const dedupe = key || `${record.path || ""}#${record.line}`;
    if (seen.has(dedupe)) {
      return;
    }
    seen.add(dedupe);
    rows.push(
      Object.freeze({
        kind: "current",
        path: record.path,
        blockId: record.blockId || null,
        route: record.route || dependencyStageRouteOf(record.path || ""),
        note: record.note || dependencyStageBasenameOf(record.path || ""),
        line: record.line,
        rawLine: record.rawLine,
        status: record.status,
        displayText: record.displayText || record.text,
        text: record.text || record.displayText,
        idField: record.idField || record.existingIdField || null,
        existingBlockId: record.blockId || record.existingBlockId || null,
        existingIdField: record.idField || record.existingIdField || null,
        section: record.section || null,
        open: record.open !== false,
        blocked: record.status === "?" || record.blocked === true,
        hidden: Boolean(record.hidden),
        dependsOn: Array.isArray(record.dependsOn) ? record.dependsOn : [],
        openCount: record.openCount,
        scheduledDate: record.scheduledDate || null,
        ...extra,
      }),
    );
  };
  for (const [from, targets] of edges) {
    if (!Array.isArray(targets) || !targets.some((target) => sourceKeys.has(target))) {
      continue;
    }
    const record = byKey.get(from) || candidates.find((row) => {
      const key =
        row.path && row.blockId
          ? dependencyStageRowKey(row.path, row.blockId)
          : null;
      return key === from;
    });
    if (record && record.open === false) {
      continue;
    }
    pushRecord(record || { path: null, blockId: null, displayText: from }, {
      key: from,
    });
  }
  const cacheTasks = [];
  if (index && index.byIdField instanceof Map) {
    for (const candidate of candidates) {
      if (Array.isArray(candidate.dependsOn) && candidate.dependsOn.length > 0) {
        cacheTasks.push(candidate);
      }
    }
  }
  for (const record of cacheTasks) {
    const hits = (record.dependsOn || []).some((id) =>
      sourceIds.has(normalizeBulletPropertyValue(id)),
    );
    if (!hits || record.open === false) {
      continue;
    }
    pushRecord(record);
  }
  return Object.freeze(rows);
}

function blocksStageRowKey(row) {
  if (!row) {
    return null;
  }
  if (row.path && row.blockId) {
    return dependencyStageRowKey(row.path, row.blockId);
  }
  return null;
}

function blocksStageLinkedCount(candidate, sources, edges) {
  const sourceList = Array.isArray(sources) ? sources : [];
  if (sourceList.length === 0) {
    return 0;
  }
  const dependsOn = new Set(
    (Array.isArray(candidate.dependsOn) ? candidate.dependsOn : []).map(
      (id) => normalizeBulletPropertyValue(id),
    ),
  );
  const key = blocksStageRowKey(candidate);
  const edgeTargets =
    key && edges instanceof Map ? edges.get(key) || [] : [];
  let count = 0;
  for (const source of sourceList) {
    const aliases = Array.isArray(source.aliases) ? source.aliases : [];
    const hit =
      (source.key && edgeTargets.includes(source.key)) ||
      aliases.some((alias) => dependsOn.has(alias));
    if (hit) {
      count += 1;
    }
  }
  return count;
}

function blocksStageIsLastReason(candidate, sources, edges, files) {
  const linked = blocksStageLinkedCount(candidate, sources, edges);
  if (linked <= 0) {
    return false;
  }
  const key = blocksStageRowKey(candidate);
  const edgeCount =
    key && edges instanceof Map && edges.get(key)
      ? edges.get(key).length
      : 0;
  const open =
    Number.isInteger(candidate.openCount) && candidate.openCount >= 0
      ? candidate.openCount
      : edgeCount;
  if (open > linked) {
    return false;
  }
  const content =
    files instanceof Map
      ? files.get(normalizeVaultRelativePath(candidate.path || ""))
      : null;
  const rawLine =
    candidate.rawLine ||
    (typeof content === "string" && Number.isInteger(candidate.line)
      ? String(content.split(/\r?\n/)[candidate.line] || "")
      : "");
  if (taskHasProjectBlockedTag(rawLine)) {
    return false;
  }
  if (
    rawLine &&
    dependencyParentHasFutureSchedule(rawLine)
  ) {
    return false;
  }
  return true;
}

function compareBlocksStageResults(left, right, sourcePath, todayMap) {
  const leftHidden = Boolean(left.hidden);
  const rightHidden = Boolean(right.hidden);
  if (leftHidden !== rightHidden) {
    return leftHidden ? 1 : -1;
  }
  const leftKey = blocksStageRowKey(left);
  const rightKey = blocksStageRowKey(right);
  const leftToday = leftKey && todayMap.has(leftKey) ? todayMap.get(leftKey) : null;
  const rightToday = rightKey && todayMap.has(rightKey) ? todayMap.get(rightKey) : null;
  if (leftToday || rightToday) {
    if (!leftToday) {
      return 1;
    }
    if (!rightToday) {
      return -1;
    }
    if (leftToday.order !== rightToday.order) {
      return leftToday.order - rightToday.order;
    }
  }
  const lane = (status) =>
    status === "/" ? 0 : status === "*" ? 1 : status === " " ? 2 : 3;
  const leftLane = lane(left.status);
  const rightLane = lane(right.status);
  if (leftLane !== rightLane && (leftLane <= 1 || rightLane <= 1)) {
    if (leftLane <= 1 && rightLane <= 1) {
      return leftLane - rightLane;
    }
    if (leftLane <= 1) {
      return -1;
    }
    if (rightLane <= 1) {
      return 1;
    }
  }
  const leftSame = left.path === sourcePath;
  const rightSame = right.path === sourcePath;
  if (leftSame !== rightSame) {
    return leftSame ? -1 : 1;
  }
  if (leftSame && rightSame) {
    return (left.line || 0) - (right.line || 0);
  }
  if (leftLane !== rightLane) {
    return leftLane - rightLane;
  }
  if (left.path !== right.path) {
    return String(left.path || "") < String(right.path || "") ? -1 : 1;
  }
  return (left.line || 0) - (right.line || 0);
}

function blocksStageGuard(candidate, sources, edges, files, labelByKey) {
  const sourceList = Array.isArray(sources) ? sources : [];
  const candidateKey = blocksStageRowKey(candidate);
  const labelCycle = (cycle) =>
    Object.freeze(
      (Array.isArray(cycle) ? cycle : []).map((key) =>
        labelByKey.has(key) ? labelByKey.get(key) : key,
      ),
    );
  const content =
    files instanceof Map
      ? files.get(normalizeVaultRelativePath(candidate.path || ""))
      : null;
  if (
    typeof content === "string" &&
    Number.isInteger(candidate.line) &&
    taskDependsOnLineIsMalformed(content, candidate.line)
  ) {
    return {
      disabled: true,
      reason: "its Depends-On line is malformed",
      cycle: null,
      cycleLabels: null,
    };
  }
  const candidateIsPrj =
    typeof content === "string" && Number.isInteger(candidate.line)
      ? Boolean(
          isProjectPrjDependencyParent(
            content,
            candidate.path,
            candidate.line,
          ),
        )
      : Boolean(candidate.isProjectPrj);
  const descendantPaths = new Set(
    (
      candidateIsPrj && Array.isArray(candidate.projectDescendantPaths)
        ? candidate.projectDescendantPaths
        : []
    ).map((path) => normalizeVaultRelativePath(path)),
  );
  if (candidateIsPrj && descendantPaths.size === 0 && files instanceof Map) {
    for (const path of collectProjectDescendantPathsFromNotes(
      candidate.path,
      files,
    )) {
      descendantPaths.add(path);
    }
  }
  for (const source of sourceList) {
    if (
      source.path === candidate.path &&
      source.line === candidate.line
    ) {
      const selfCycle = Object.freeze([source.key || candidateKey].filter(Boolean));
      return {
        disabled: true,
        reason: "this task",
        cycle: selfCycle,
        cycleLabels: labelCycle(selfCycle),
      };
    }
    if (candidateIsPrj && source.path === candidate.path) {
      return {
        disabled: true,
        reason: "inside this project",
        cycle: null,
        cycleLabels: null,
      };
    }
    if (
      candidateIsPrj &&
      source.path &&
      descendantPaths.has(normalizeVaultRelativePath(source.path))
    ) {
      return {
        disabled: true,
        reason: "inside a sub-project of this project",
        cycle: null,
        cycleLabels: null,
      };
    }
    if (candidateKey && source.key) {
      let cycle = findDependencyStageCycle(edges, candidateKey, source.key);
      if (!cycle && candidateIsPrj) {
        const residentKeys = Array.isArray(candidate.projectResidentKeys)
          ? candidate.projectResidentKeys
          : typeof content === "string"
            ? projectDependentResidentKeys(
                content,
                candidate.path,
                candidate.line,
              )
            : [];
        for (const residentKey of residentKeys) {
          if (!residentKey || residentKey === candidateKey) {
            continue;
          }
          cycle = findDependencyStageCycle(edges, residentKey, source.key);
          if (cycle) {
            break;
          }
        }
      }
      if (cycle) {
        return {
          disabled: true,
          reason: "would create a cycle",
          cycle: Object.freeze(cycle),
          cycleLabels: labelCycle(cycle),
        };
      }
    }
  }
  return { disabled: false, reason: null, cycle: null, cycleLabels: null };
}

function decorateBlocksVaultStage(stage, options = {}) {
  if (!stage) {
    return null;
  }
  const sources =
    Array.isArray(options.sources) && options.sources.length > 0
      ? options.sources
      : collectBlocksStageSources(stage);
  const files = stage.files instanceof Map ? stage.files : new Map();
  let todayLinks = Array.isArray(options.todayLinks)
    ? options.todayLinks
    : Array.isArray(stage.todayLinks)
      ? stage.todayLinks
      : [];
  if (todayLinks.length === 0 && options.dailyPath && files.has(options.dailyPath)) {
    todayLinks = collectBlocksStageTodayLinks(
      files.get(options.dailyPath),
      options.dailyPath,
      stage.index,
    );
  }
  const current = collectBlocksStageCurrent(stage, sources);
  const edges = stage.edges instanceof Map ? stage.edges : new Map();
  let freesCount = 0;
  for (const row of current) {
    if (blocksStageIsLastReason(row, sources, edges, files)) {
      freesCount += 1;
    }
  }
  const primary = sources[0];
  const title =
    sources.length > 1
      ? `\ud83e\uddf1 Blocks \u00b7 ${formatCountLabel(sources.length, "task")}`
      : `\ud83e\uddf1 Blocks \u00b7 ${String(
          (primary && primary.displayText) || "",
        ).slice(0, 48)}`;
  const linkedKeys = new Set();
  for (const row of current) {
    const key = blocksStageRowKey(row);
    if (key) {
      linkedKeys.add(key);
    }
  }
  return {
    ...stage,
    blocks: true,
    sources: Object.freeze(sources),
    current: Object.freeze(current),
    todayLinks: Object.freeze(todayLinks),
    linkedKeys,
    title,
    openCount: current.length,
    freesCount,
    poolSize: Array.isArray(stage.candidates) ? stage.candidates.length : 0,
  };
}

function planBlocksStageView(args = {}) {
  const sources = Array.isArray(args.sources) ? args.sources : [];
  const current = Array.isArray(args.current) ? args.current : [];
  const pool = Array.isArray(args.candidates) ? args.candidates : [];
  const query = String(args.query || "");
  const edges = args.edges || new Map();
  const files = args.files instanceof Map ? args.files : new Map();
  const todayMap = blocksStageTodayMap(args.todayLinks);
  const sourcePath = sources[0] ? sources[0].path : "";
  const sourceKeys = new Set(sources.map((source) => source.key).filter(Boolean));
  const sourceLines = new Set(
    sources.map((source) => `${source.path}\x00${source.line}`),
  );
  const maxRows = Math.max(
    1,
    Math.floor(numericOrDefault(args.maxRows, DEPENDENCY_STAGE_MAX_ROWS)),
  );
  const sourceCount = Math.max(1, sources.length || 1);
  const labelByKey = new Map();
  for (const row of [...current, ...pool, ...sources]) {
    if (!row) {
      continue;
    }
    const key = blocksStageRowKey(row) || row.key || null;
    const label = row.displayText || row.text || null;
    if (key && label && !labelByKey.has(key)) {
      labelByKey.set(key, label);
    }
  }
  const fullyLinked = [];
  const partialLinked = [];
  for (const row of current) {
    const linked = blocksStageLinkedCount(row, sources, edges);
    if (linked > 0 && linked < sourceCount) {
      partialLinked.push(row);
      continue;
    }
    fullyLinked.push(row);
  }
  const markedCurrent = fullyLinked.map((row, index) => {
    const lastReason = blocksStageIsLastReason(row, sources, edges, files);
    const key = blocksStageRowKey(row);
    const todayLink = key && todayMap.has(key) ? todayMap.get(key) : null;
    return Object.freeze({
      kind: "local-task",
      ...row,
      stageSection: "current",
      alreadyLinked: true,
      firstInSection: index === 0,
      headerSection: index === 0 ? "current" : null,
      lastReason,
      todayLink,
      linkedSourceCount: sourceCount,
      sourceCount,
      linkState: "all",
      needsPromptForAdd: false,
      needsBlockIdPrompt: false,
      markKey:
        row.markKey ||
        (row.path
          ? `${normalizeVaultRelativePath(row.path)}#${row.blockId || `line:${row.line}`}`
          : row.line),
      noteLabel:
        row.path && row.path !== sourcePath
          ? dependencyStageBasenameOf(row.path)
          : null,
      disabled: false,
      disabledReason: null,
      cycle: null,
      cycleLabels: null,
    });
  });
  const seen = new Set(
    fullyLinked
      .map((row) => blocksStageRowKey(row))
      .filter(Boolean),
  );
  const fresh = [];
  for (const row of partialLinked) {
    const key = blocksStageRowKey(row);
    if (key) {
      seen.add(key);
    }
    fresh.push({
      candidate: row,
      key,
      linkedCount: blocksStageLinkedCount(row, sources, edges),
    });
  }
  for (const candidate of pool) {
    const lineKey = `${normalizeVaultRelativePath(candidate.path || "")}\x00${candidate.line}`;
    if (sourceLines.has(lineKey)) {
      continue;
    }
    const key = blocksStageRowKey(candidate);
    if (key && sourceKeys.has(key)) {
      continue;
    }
    const linkedCount = blocksStageLinkedCount(candidate, sources, edges);
    if (linkedCount > 0 && linkedCount === sourceCount) {
      continue;
    }
    if (key && seen.has(key)) {
      continue;
    }
    if (key) {
      seen.add(key);
    }
    fresh.push({ candidate, key, linkedCount });
  }
  // One RESULTS list ranked by score (§15.3): status only breaks
  // exact-score ties (open before Blocked, then the stage's canonical
  // order), and the cap counts this merged order.
  const isBlockedRow = (candidate) =>
    Boolean(candidate.blocked || candidate.status === "?");
  const emptyQuery = !query.trim();
  const entryByCandidate = new Map(
    fresh.map((entry) => [entry.candidate, entry]),
  );
  const ordered = orderDependencyStageMatches(
    fresh.map((entry) => entry.candidate),
    query,
    (left, right) =>
      Number(isBlockedRow(left)) - Number(isBlockedRow(right)) ||
      compareBlocksStageResults(left, right, sourcePath, todayMap),
  ).map((candidate) => entryByCandidate.get(candidate));
  const room = Math.max(0, maxRows - markedCurrent.length);
  const picked = ordered.slice(0, room);
  const statusClasses = picked.map((entry) =>
    isBlockedRow(entry.candidate) ? "blocked" : "results",
  );
  const headers = dependencyStageHeaderSections(statusClasses, emptyQuery);
  const shape = (entry, section, header) => {
    const candidate = entry.candidate;
    const verdict = blocksStageGuard(
      candidate,
      sources,
      edges,
      files,
      labelByKey,
    );
    const key = blocksStageRowKey(candidate);
    const todayLink = key && todayMap.has(key) ? todayMap.get(key) : null;
    const content =
      files instanceof Map
        ? files.get(normalizeVaultRelativePath(candidate.path || ""))
        : null;
    const isProjectPrj =
      typeof content === "string" && Number.isInteger(candidate.line)
        ? Boolean(
            isProjectPrjDependencyParent(
              content,
              candidate.path,
              candidate.line,
            ),
          )
        : false;
    let projectWaitCount = 0;
    let projectPomodoroCount = 0;
    let projectResidentKeys = Object.freeze([]);
    if (isProjectPrj && typeof content === "string") {
      const info = getProjectPrjDependencyResidents(content, candidate.path);
      projectResidentKeys = projectDependentResidentKeys(
        content,
        candidate.path,
        candidate.line,
      );
      if (info && Array.isArray(info.residents)) {
        projectWaitCount = info.residents.length + 1;
        for (const resident of info.residents) {
          const residentKey =
            resident.blockId &&
            dependencyStageRowKey(candidate.path, resident.blockId);
          if (residentKey && todayMap.has(residentKey)) {
            projectPomodoroCount += 1;
          }
        }
        if (todayLink) {
          projectPomodoroCount += 1;
        }
      }
    }
    let waitsOn = null;
    let blockedBadge = null;
    if (section === "blocked") {
      const open =
        Number.isInteger(candidate.openCount) && candidate.openCount >= 0
          ? candidate.openCount
          : 0;
      if (open >= 1) {
        waitsOn = open;
        blockedBadge = `\ud83d\udd12 waits on ${open}`;
      } else {
        const scheduled =
          typeof candidate.scheduledDate === "string" &&
          /^\d{4}-\d{2}-\d{2}$/.test(candidate.scheduledDate)
            ? candidate.scheduledDate
            : null;
        blockedBadge = scheduled
          ? `\ud83d\udd12 scheduled ${scheduled}`
          : "\ud83d\udd12 blocked";
      }
    }
    const linkedCount = entry.linkedCount || 0;
    return Object.freeze({
      kind: "local-task",
      stageSection: section,
      firstInSection: header !== null,
      headerSection: header,
      path: candidate.path,
      blockId: candidate.blockId,
      route: candidate.route,
      note: candidate.note,
      noteLabel:
        candidate.path && candidate.path !== sourcePath
          ? dependencyStageBasenameOf(candidate.path)
          : null,
      line: candidate.line,
      rawLine: candidate.rawLine,
      status: candidate.status,
      displayText: candidate.displayText,
      text: candidate.text,
      searchText: [
        candidate.displayText,
        candidate.route,
        candidate.blockId ? `${candidate.route}:${candidate.blockId}` : "",
        candidate.blockId || "",
        candidate.section || "",
        candidate.note || "",
      ]
        .filter(Boolean)
        .join(" "),
      value:
        candidate.idField ||
        (candidate.blockId
          ? tryDependencyId(candidate.path, candidate.blockId)
          : null) ||
        "",
      alreadyLinked: false,
      linkedSourceCount: linkedCount,
      sourceCount,
      linkState:
        linkedCount === 0
          ? "none"
          : linkedCount >= sourceCount
            ? "all"
            : "mixed",
      needsBlockIdPrompt: false,
      needsPromptForAdd: false,
      hidden: candidate.hidden,
      section: candidate.section,
      markKey: `${candidate.path}#${
        candidate.line >= 0
          ? candidate.line
          : candidate.blockId || candidate.displayText
      }`,
      disabled: verdict.disabled,
      disabledReason: verdict.reason,
      cycle: verdict.cycle,
      cycleLabels: verdict.cycleLabels || null,
      waitsOn,
      blockedBadge,
      openCount: candidate.openCount,
      lastReason: false,
      todayLink,
      isProjectPrj,
      projectWaitCount,
      projectPomodoroCount,
      projectResidentKeys,
      dependsOn: Array.isArray(candidate.dependsOn) ? candidate.dependsOn : [],
    });
  };
  const out = [...markedCurrent];
  picked.forEach((entry, index) =>
    out.push(shape(entry, statusClasses[index], headers[index])),
  );
  const hiddenCount = Math.max(0, ordered.length - picked.length);
  if (hiddenCount > 0) {
    out.push(
      Object.freeze({
        kind: "stage-more",
        stageSection: statusClasses[statusClasses.length - 1] || "results",
        firstInSection: false,
        headerSection: null,
        path: null,
        blockId: null,
        displayText: `type to search ${hiddenCount} more`,
        text: `type to search ${hiddenCount} more`,
        searchText: "",
        hiddenCount,
        disabled: true,
        disabledReason: `type to search ${hiddenCount} more`,
        cycle: null,
        cycleLabels: null,
        waitsOn: null,
      }),
    );
  }
  return Object.freeze(out);
}

function planBlocksStageItemsFromVault(stage, query) {
  if (!stage) {
    return Object.freeze([]);
  }
  const items = planBlocksStageView({
    sources: stage.sources,
    current: stage.current,
    candidates: stage.candidates,
    query: query || "",
    edges: stage.edges,
    files: stage.files,
    todayLinks: stage.todayLinks,
  });
  return planTieVisibilityItems(items, stage, "blocks", query || "");
}
// ---- src/303-blocks-stage-copy.js ----
// Blocks… stage copy: consequence strip, subtitle, and lane phrases
// (`docs/task-dependencies.md` §15.4 / §15.7).

function blocksStageLanePhrase(status) {
  if (status === "/") {
    return "this task takes In Progress";
  }
  if (status === "*") {
    return "this task takes Next";
  }
  return null;
}

function blocksStagePomodoroPhrase(todayLink) {
  if (!todayLink) {
    return null;
  }
  const range = todayLink.range ? ` ${todayLink.range}` : "";
  const running = todayLink.running ? " (running)" : "";
  let phrase = `\u26a0 removes its link from ${todayLink.label}${range}${running}`;
  const notes = Math.floor(numericOrDefault(todayLink.childNotes, 0));
  if (notes > 0) {
    phrase += ` and the ${notes} note${notes === 1 ? "" : "s"} under it`;
  }
  return phrase;
}

function blocksStageTiePrefix(item, text) {
  return item && item.tieConvert && tieVisibilityHasPlainLink(item.tieInfo)
    ? `Replaces the 🪢 link · ${text}`
    : text;
}

function blocksStageConsequenceStrip(item, context = {}) {
  const sources = Array.isArray(context.sources) ? context.sources : [];
  const marked = Array.isArray(context.marked) ? context.marked : [];
  if (marked.length > 0) {
    let add = 0;
    let remove = 0;
    let takes = null;
    let pomodoro = 0;
    for (const row of marked) {
      if (row.alreadyLinked || row.stageSection === "current") {
        remove += 1;
      } else {
        add += 1;
        const lane = blocksStageLanePhrase(row.status);
        if (lane === "this task takes In Progress") {
          takes = "/";
        } else if (lane && takes !== "/") {
          takes = "*";
        }
        if (row.todayLink) {
          pomodoro += 1;
        }
      }
    }
    const parts = [`\u21b5 blocks ${add}`];
    if (add === 0) {
      parts[0] = `\u21b5 removes ${remove}`;
    } else if (remove > 0) {
      parts[0] = `\u21b5 blocks ${add} \u00b7 removes ${remove}`;
    }
    // A project N is never raised, so the strip never promises a lane.
    if (sources.some((source) => source.isProjectPrj)) {
      takes = null;
    }
    if (takes === "/") {
      parts.push("this task takes In Progress");
    } else if (takes === "*") {
      parts.push("this task takes Next");
    }
    if (pomodoro > 0) {
      parts.push(
        `\u26a0 removes ${pomodoro} Pomodoro link${pomodoro === 1 ? "" : "s"}`,
      );
    }
    return blocksStageTiePrefix(item, parts.join(" \u00b7 "));
  }
  if (!item || item.kind === "stage-more") {
    return "";
  }
  if (item.disabled) {
    if (
      item.disabledReason === "would create a cycle" &&
      item.tieInfo && item.tieInfo.waitsOn &&
      typeof tieVisibilityTieChangePlan === "function"
    ) {
      const owner = sources[0] || null;
      const planned = tieVisibilityTieChangePlan(
        context.stage,
        context.plugin,
        owner,
        item,
        "other-waits",
      );
      if (planned && planned.kind === "change" && planned.reversing === true) {
        return "⟲ This task waits on it · ⌃⇧B reverses";
      }
    }
    if (
      item.disabledReason === "would create a cycle" &&
      Array.isArray(item.cycleLabels) &&
      item.cycleLabels.length > 0
    ) {
      return `\u27f2 would create a cycle: ${item.cycleLabels.join(" \u2192 ")}`;
    }
    return item.disabledReason || "";
  }
  if (item.stageSection === "current") {
    return item.lastReason
      ? "Stops waiting on this \u00b7 Ready again"
      : "Stops waiting on this \u00b7 still Blocked";
  }
  if (item.isProjectPrj) {
    const wait = Math.max(
      0,
      Math.floor(numericOrDefault(item.projectWaitCount, 0)),
    );
    const links = Math.max(
      0,
      Math.floor(numericOrDefault(item.projectPomodoroCount, 0)),
    );
    const parts = ["Project becomes Blocked"];
    if (wait > 0) {
      parts.push(`${wait} ${wait === 1 ? "task waits" : "tasks wait"}`);
    }
    if (links > 0) {
      parts.push(`\u26a0 removes ${links} Pomodoro link${links === 1 ? "" : "s"}`);
    }
    return blocksStageTiePrefix(item, parts.join(" \u00b7 "));
  }
  if (item.stageSection === "blocked") {
    // Counted after the add, so this task is one of the open reasons.
    const open =
      Math.max(
        0,
        Math.floor(numericOrDefault(item.waitsOn, item.openCount || 0)),
      ) + 1;
    return blocksStageTiePrefix(item, `Also waits on this (${open} open)`);
  }
  const parts = ["Becomes Blocked until this is done"];
  const strongest = sources.some((source) => source.isProjectPrj)
    ? null
    : blocksStageLanePhrase(item.status);
  if (strongest) {
    parts.push(strongest);
  }
  const pomodoro = blocksStagePomodoroPhrase(item.todayLink);
  if (pomodoro) {
    parts.push(pomodoro);
  }
  return blocksStageTiePrefix(item, parts.join(" \u00b7 "));
}

function blocksStageSubtitle(stage, markedDiff, options = {}) {
  const currentCount = Array.isArray(stage && stage.current)
    ? stage.current.length
    : 0;
  const frees = Math.max(
    0,
    Math.floor(numericOrDefault(stage && stage.freesCount, 0)),
  );
  const pool = Math.max(
    0,
    Math.floor(numericOrDefault(stage && stage.poolSize, 0)),
  );
  const needsId = options.needsId === true;
  const plainLinks = tieVisibilityCountPhrase(options.plainLinkCount, "plain-link");
  const marked = markedDiff && typeof markedDiff === "object" ? markedDiff : null;
  if (marked && (marked.add > 0 || marked.remove > 0 || marked.needId > 0)) {
    const parts = [];
    if (marked.add > 0) {
      parts.push(`${marked.add} to block`);
    }
    if (marked.remove > 0) {
      parts.push(`${marked.remove} to remove`);
    }
    parts.push("\u21b5 to apply");
    if (needsId) {
      parts.push("names this task first");
    }
    return parts.join(" \u00b7 ");
  }
  let head =
    currentCount === 0
      ? `Blocks nothing yet \u00b7 searching ${pool} open tasks`
      : `Blocks ${currentCount} \u00b7 frees ${frees} \u00b7 searching ${pool} open tasks`;
  if (plainLinks) {
    head = head.replace(`searching ${pool} open tasks`, `${plainLinks} \u00b7 searching ${pool} open tasks`);
  }
  // \u21e5 marks are off in counted sessions, so the hint is dropped there.
  return options.counted === true ? head : `${head} \u00b7 \u21e5 to mark several`;
}
