    if (!navApplySettledEditorPostimage(
      this.plugin,
      this.editor,
      ownerPath,
      originalContent,
      working,
      { annotation: BLOCKS_MACHINE_WRITE_ANNOTATION, today: new Date() },
    ).ok) {
      new Notice("Could not update counted dependencies; no tasks were updated");
      return false;
    }
