    let task = resolveCopyCardTask(lines, singleSelection);
    const link = task.state === "none"
      ? resolveCopyCardTaskLink(lines, singleSelection)
      : null;
    if (!link) {
      this.openCopyCardSnapshot({ file, view, editor, lines, selections, task });
      return;
    }

