        const path = String(plan.cursor.path || "");
        const line = Math.floor(Number(plan.cursor.line));
        const stagedLines = splitMarkdownContent(String(postimages[path] || "")).lines;
        const text = line > 0 ? String(stagedLines[line - 1] || "") : "";
