  if (backlinks > 0) {
    parts.push(
      pluralizeDeleteGuard(
        backlinks,
        "1 note links here",
        "{n} notes link here",
      ),
    );
  }
  const openTasks = facts && Number(facts.openTaskCount);
  if (openTasks > 0) {
    parts.push(
      pluralizeDeleteGuard(openTasks, "1 open task", "{n} open tasks"),
    );
  }
