  const sourceLines = Array.isArray(lines) ? lines : [];
  const info = options && typeof options === "object" ? options : {};
  const planned =
    Number.isInteger(info.line) && info.line >= 1 ? info.line - 1 : Number.NaN;
  const digest = parseGoToTaskRefDigest(info.ref);
